-- DIRA LEARN - installation in the Supabase SQL Editor, STEP 4 of 5: data part 2 of 2
-- Generated by tools/baseline/build_install.py from supabase/baseline - do not edit by hand.
-- Paste the WHOLE file into a new SQL Editor query and press Run. It is one transaction: if anything fails,
-- nothing of this step is kept, and you can simply run it again after the cause is fixed.
-- The curriculum teaching notes, then the installation is recorded as complete. Refuses unless STEPS 1-3 are installed.

do $steps$
declare v text;
begin
  if pg_catalog.to_regclass('supabase_migrations.dira_install_steps') is not null then
    execute 'select string_agg(step::text, '','' order by step) from supabase_migrations.dira_install_steps' into v;
  end if;
  if coalesce(v, 'none') <> '1,2,3' then
    raise exception 'STOP: this is STEP-4. It needs exactly the steps before it installed (1,2,3); this project has: %. Run STEP-0 to see what to do next. Nothing was changed.', coalesce(v, 'none');
  end if;
end $steps$;
alter table public.curriculum_teaching_notes disable trigger user; insert into public.curriculum_teaching_notes(id, session_id, content, updated_by, updated_at, created_at) select id, session_id, content, updated_by, updated_at, created_at from jsonb_populate_recordset(null::public.curriculum_teaching_notes, $dira_json$[{"id":"0d4fa9c3-21dc-4007-9246-62b117ec3427","session_id":"c3dcef6d-faf9-47c9-8df7-cdb847f057e2","content":{"version": "V13.2", "segments": [{"steps": ["Ask four learners to share one surprise from their interviews (a quote, a number or a behaviour).", "Highlight learners whose interviews changed their idea - that is a success, not a failure."], "title": "Recap and interview findings"}, {"steps": ["Draw the value proposition canvas. Customer profile (circle) - jobs, pains, gains from interviews. Value map (square) - products and services, pain relievers (how you reduce pains), gain creators (how you create gains). Fit = your pain relievers and gain creators address the most important pains and gains.", "Worked example - laundry pick-up for students. Pains - no space to dry clothes, rain, time lost walking to the laundry. Pain relievers - pick-up from the hostel, dried and folded within 24 hours. Gains - more free time, clean clothes for events. Gain creators - weekly subscription, M-Pesa payment, WhatsApp reminders.", "Value proposition statement formula: 'For [target customer] who [need or problem], [business name] is a [category] that [key benefit]. Unlike [alternative], we [key difference].' Example - 'For students in Nakuru hostels who have no time or space to wash and dry clothes, Fresh Fold is a laundry pick-up service that returns clothes clean and folded within 24 hours. Unlike hand-washing or walking to town, we collect from your hostel and you pay by M-Pesa.'", "Differentiation: why customers would choose you over the current alternative - faster, cheaper, closer, more reliable, more convenient, better quality."], "title": "Value propositions"}, {"steps": ["Learners fill the customer profile with evidence from their interviews (mark each item with the number of interviewees who mentioned it).", "They fill the value map and check that each top pain and gain has a pain reliever or gain creator.", "They write the one-sentence value proposition statement and read it to a partner, who says whether it is clear and believable."], "title": "Your value proposition"}, {"steps": ["Explain the simplified business model canvas - nine boxes: customers (who); value proposition (what); channels (how they find, buy and receive); customer relationships (how you keep them); revenue streams (how money comes in); key activities (what you must do); key resources (what you need - people, equipment, money, skills); key partners (who helps - suppliers, riders, landlords); costs (what you spend).", "Fill the canvas for Fresh Fold as a worked example, box by box.", "Business model types with Kenyan examples: product sales (a juice vendor); services (a mobile phone repair shop); subscriptions (weekly laundry, gym membership); commissions and marketplaces (platforms that connect sellers and buyers and take a fee); rental (renting out tents and chairs for events); freemium (free basic service, paid premium).", "Ask learners which model type fits their idea and whether a different one could work better."], "title": "Business models and the simplified canvas"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["Explain that channels and customer relationships are where marketing lives in a business model. For most young Kenyan businesses, the main channels are digital: social media (Facebook, Instagram, TikTok, LinkedIn), WhatsApp Business (catalogue, quick replies, status), content (photos, graphics in tools like Canva, captions with calls to action), and sometimes advertising and search (a Google Business Profile so people find you on Maps).", "At the business-model level, decide three things: which two channels will bring your first customers, what one message will make them act, and how you will measure whether the channel works (enquiries, orders, cost per customer).", "Explain that session 6 turns this into a one-page marketing plan, and that the Digital Marketing track teaches these channels in depth. Here the question is only whether the channels fit the customers and the costs in the model."], "title": "Reaching and keeping customers - marketing in the business model"}, {"steps": ["Learners complete the simplified canvas for their idea on one page, using their value proposition and interview evidence.", "In the channels box, they choose two first channels and how they will measure them.", "They mark each box as 'evidence' (from interviews or data) or 'assumption'.", "The facilitator circulates and asks 'how do you know?' about key boxes (revenue and channels especially)."], "title": "Map your one-page business model"}, {"steps": ["In groups of three, one learner presents their model in 2 minutes; the other two act as challengers with question cards: 'Why would customers switch?', 'How will the first 10 customers find you?', 'What does one customer cost you?', 'What happens if your key partner lets you down?', 'Which box is your biggest assumption?' Rotate.", "Each learner notes the two hardest questions and revises their model or adds the question to their testing list for session 7."], "title": "Peer challenge"}, {"steps": ["Ask learners to name the box in their model with the weakest evidence.", "Set the homework."], "title": "Wrap-up and homework"}], "facilitator": {"delivery": ["Keep marketing content at the business-model level; learners who want more should be pointed to the Digital Marketing track resources.", "Make learners show evidence; praise honest 'assumption' labels."], "preparation": ["Prepare the canvases, the Fresh Fold worked example and the challenge question cards.", "Note that this session's curriculum record was approved by DIRA on 8 Nov 2026; deliver its approved activities (simplified business model canvas and peer challenge) and output (one-page business model) as written."], "after_session": ["Review business models and note the biggest assumption for each learner to test in session 7.", "Record attendance."], "inclusion_and_safeguarding": ["Keep the peer challenge respectful - challenge the idea, never the person."]}, "demonstrations": [{"steps": ["Complete the canvas and statement for Fresh Fold laundry pick-up live."], "title": "Value proposition canvas worked example"}, {"steps": ["Fill all nine boxes for Fresh Fold, marking evidence and assumptions."], "title": "Business model canvas worked example"}], "assessment_guides": [{"guide": "Names the target customer, need, category, key benefit and difference from alternatives.", "question": "Write your value proposition statement."}, {"guide": "Any five of customers, value proposition, channels, relationships, revenue streams, key activities, key resources, key partners, costs.", "question": "Name five boxes of the simplified business model canvas."}, {"guide": "Subscription (recurring payment for ongoing service); could also be a service model.", "question": "Which business model type is a weekly laundry service, and why?"}, {"guide": "Specific channels linked to the target customer and a measurable indicator.", "question": "What two channels will bring your first customers, and how will you measure them?"}, {"guide": "Honest identification, usually revenue, channels or willingness to pay.", "question": "Which box of your model is the biggest assumption?"}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"109b1431-acae-48f8-9034-7b1e8ecbe21c","session_id":"ad880c63-14d6-408b-8b6a-646e961c1bf6","content":{"version": "V13.2", "segments": [{"steps": ["Ask learners to share one cost they found that surprised them (rent, permits, packaging, transport).", "Explain that many small businesses in Kenya fail not because nobody buys, but because they do not know their numbers. Today is about numbers."], "title": "Recap and cost hunt results"}, {"steps": ["Separate business and personal money: use a separate M-Pesa line, a till number or a separate account for the business. Mixing them makes it impossible to know if the business makes money.", "Records: write every sale and expense daily in a book or simple sheet; download M-Pesa statements monthly. Records help you make decisions, apply for loans and handle tax.", "Pay yourself a fixed amount instead of taking money from the till whenever you need it.", "Savings: set aside a little each week for emergencies and stock.", "Credit: digital loans are quick but can be expensive and can lead to a cycle of borrowing; late repayment can affect your credit record with credit reference bureaus. Government funds such as the Hustler Fund, chamas and SACCOs are alternatives with different terms. Before borrowing, ask - what exactly will this money buy, how will it bring more income, and what is the total amount I will repay?", "Tax basics: registering for a KRA PIN is required for many formal activities; keeping records makes tax obligations easier to meet. Check current requirements on the official KRA website."], "title": "Basic financial literacy for entrepreneurs"}, {"steps": ["Start-up costs (once, before opening): equipment, first stock, registration and permits, initial branding. Operating costs (every month): rent, stock, transport, data, wages, packaging.", "Fixed costs (same every month regardless of sales): rent, a stall fee, a salary. Variable costs (change with each unit sold): ingredients, packaging, delivery per order.", "Variable cost per unit - a juice business. Per 500 ml bottle: fruit KES 25, sugar and water KES 5, bottle and label KES 15, fruit transport share KES 5. Variable cost per bottle = KES 50 (these are also the direct costs of making the product). Fixed costs per month: stall fee KES 3,000, blender depreciation KES 500, data KES 500 = KES 4,000.", "Fully allocated unit cost = variable cost per unit + (fixed costs for the month / units sold in the month). At 300 bottles a month: 50 + 4,000 / 300 = 50 + 13.33 = about KES 63 per bottle. At only 150 bottles it rises to 50 + 26.67 = about KES 77: fixed costs spread over fewer units, so each costs more.", "Learners classify their own cost list into start-up or operating and fixed or variable."], "title": "Costing"}, {"steps": ["Cost-plus pricing: add a markup to cost. A 60% markup on the variable cost gives KES 50 + 30 = KES 80. Check it against the fully allocated unit cost at realistic sales (KES 63 at 300 bottles): KES 80 leaves about KES 17 per bottle after all costs.", "Competitor-based pricing: what do similar juice sellers charge nearby? If they charge KES 70 to 100, KES 80 fits.", "Value-based pricing: what is it worth to the customer? Fresh juice delivered to offices may be worth KES 100.", "Two floors for any price: never below the variable cost per unit (every sale would lose money), and over the month the price must be above the fully allocated unit cost at your realistic sales volume, or the business makes a loss. Then check it fits the market and reflects the value.", "Contribution per unit = price - variable cost per unit = KES 80 - 50 = KES 30. It is what each sale contributes towards fixed costs and then profit. Contribution margin = 30 / 80 = 37.5% of the price (a 60% markup on cost is a 37.5% margin on price - markup and margin are not the same).", "Break-even (units) = fixed costs / contribution per unit = 4,000 / 30 = 133.3, so 134 bottles a month (round up) - about 5.2 a day over 26 trading days, so plan for at least 6. Check: at break-even the fully allocated unit cost (50 + 4,000 / 134 = about KES 80) equals the price.", "Discounts: a 10% discount makes the price KES 72, so contribution falls from KES 30 to KES 22 per bottle - a 27% drop - and break-even rises from 134 to 182 bottles (4,000 / 22 = 181.8). Use discounts carefully."], "title": "Pricing and break-even"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["Simple monthly profit at 300 bottles: revenue 300 x KES 80 = KES 24,000; cost of goods sold (the direct costs of the bottles sold) 300 x KES 50 = KES 15,000; gross profit = revenue - cost of goods sold = KES 9,000; minus fixed costs KES 4,000 = net profit KES 5,000 (before tax). Here every variable cost is a direct product cost, so gross profit equals total contribution (300 x KES 30). If a business also has variable selling costs, such as a delivery rider paid per order or an agent's commission, those reduce contribution but not gross profit, and the two figures differ. Check: fully allocated cost 300 x KES 63.33 = KES 19,000, and 24,000 - 19,000 = KES 5,000.", "Formula card for the finance template: variable cost per unit = sum of the costs of one unit; contribution per unit = price - variable cost per unit; contribution margin = contribution per unit / price; gross profit = revenue - cost of goods sold; net profit = gross profit - fixed (and other operating) costs; fully allocated unit cost = variable cost per unit + fixed costs / units; break-even units = fixed costs / contribution per unit, rounded up.", "Cash flow is the timing of money in and out. A business can be profitable on paper and still run out of cash - for example if an office pays at month-end but you must buy fruit every morning.", "Show a one-month cash-flow table by week: opening cash, cash in (sales paid), cash out (stock, rent, transport), closing cash. Show a week where closing cash goes negative and discuss solutions (smaller stock purchases, deposits from customers, shorter credit, a cash buffer).", "Credit sales and stock both tie up cash; record who owes you and follow up politely."], "title": "Revenue, expenses and cash flow"}, {"steps": ["Learners complete the finance template (Google Sheets or paper): start-up budget with real prices where possible; variable cost per unit and fully allocated unit cost at their expected sales; price with a reason (cost-plus, competitor and value checked); contribution per unit; break-even units per month; gross and net profit for the month; one-month cash flow by week with realistic sales assumptions.", "Learners highlight every number that is a guess rather than a researched price.", "The facilitator circulates, checking arithmetic and asking 'where did this number come from?'.", "Learners swap with a partner who checks one calculation."], "title": "Start-up budget and one-month cash flow"}, {"steps": ["Explain the lean one-page plan: problem, customer, value proposition, solution, channels, revenue and price, costs, key numbers (break-even, monthly target), team, next milestones and what you need (money, partners, skills).", "A full business plan is usually needed when applying for loans, grants, investors or competitions; the one-page plan is the starting point.", "Learners start their one-page plan outline, filling what they already have from sessions 3 to 5."], "title": "Lean one-page business plan"}, {"steps": ["Ask learners to share their break-even number and whether it feels achievable.", "Set the homework."], "title": "Wrap-up and homework"}], "facilitator": {"delivery": ["Go slowly on arithmetic; some learners fear numbers. Use the same example throughout.", "Praise honest 'guess' labels and push for researched prices."], "preparation": ["Prepare the finance template in Google Sheets with formulas and a paper version, and the juice worked example.", "Check current official information on KRA PIN registration and government youth funds if you plan to mention specifics; do not give financial advice beyond the basics."], "after_session": ["Check finance templates for errors and give feedback.", "Record attendance."], "inclusion_and_safeguarding": ["Money and debt can be sensitive; never ask learners about personal debts publicly.", "If a learner discloses serious financial exploitation or pressure, follow up privately and use the DIRA LEARN support routes.", "Consent and privacy: before using an identifiable person (face, voice or name), a photograph of someone, or a real business's name, logo, prices, customer details or results, the learner gets permission from that person or owner - in writing (a WhatsApp message is enough) for anything shown outside the class. Never children. Learners who cannot or do not wish to publish publicly use the private or simulated option, which is assessed with the same rubric and never marked down."]}, "demonstrations": [{"steps": ["Walk through variable cost per unit, fully allocated unit cost, pricing, contribution per unit, break-even, gross and net profit, and a cash-flow table for the juice example, using the formula card."], "title": "Juice business numbers"}, {"steps": ["Show a profitable month that still has a negative cash week, and two ways to fix it."], "title": "Cash runs out"}], "assessment_guides": [{"guide": "Rent is fixed; packaging is variable.", "question": "Classify rent and packaging as fixed or variable costs."}, {"guide": "A price above KES 150 (for example KES 190-200), justified by value or difference and checked against competitors; never below KES 120, and above KES 150 to make a profit at the expected volume.", "question": "Your variable cost per unit is KES 120, your fully allocated unit cost at expected sales is KES 150, and competitors charge KES 180 to 220. Suggest a price and explain."}, {"guide": "6,000 / 40 = 150 units a month.", "question": "Fixed costs are KES 6,000 a month and contribution per unit is KES 40. What is break-even?"}, {"guide": "Contribution = 90 - 50 = KES 40; fully allocated unit cost = 50 + 4,000 / 200 = KES 70.", "question": "Variable cost per unit is KES 50, fixed costs are KES 4,000 a month and you expect to sell 200 units at KES 90. Work out the contribution per unit and the fully allocated unit cost."}, {"guide": "Timing - money goes out before it comes in (stock, credit sales, irregular payments).", "question": "Why can a profitable business run out of cash?"}, {"guide": "What it will buy and how it brings income; total repayment and ability to repay; alternatives.", "question": "Name two questions to ask before taking a loan."}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"18aa1349-8bd8-45da-82f3-24eed9daeb2f","session_id":"810c6163-429e-4db5-b72a-b88bfd6e88cd","content":{"version": "V13.2", "segments": [{"steps": ["Learners share views, watch time or comments from their published video and one thing they learned.", "Introduce today - design, brand and the rules that protect creators and the people they feature."], "title": "Recap and video results"}, {"steps": ["Teach CRAP with good and bad examples: Contrast (make the important thing different - size, colour, weight); Repetition (repeat colours, fonts and styles so it feels like one design); Alignment (everything lines up with something; use the grid); Proximity (group related items, separate unrelated ones).", "Typography: maximum two fonts - one for headings, one for body; use size and weight for hierarchy; avoid decorative fonts for long text; check readability at phone size.", "Colour: a palette of two or three main colours plus neutrals; colours carry meaning (green - fresh, growth; red - urgency, passion); ensure strong contrast between text and background.", "Grids and hierarchy: decide the one thing viewers should notice first, second and third. Use margins and consistent spacing.", "Redesign a cluttered event poster live (a youth football tournament poster with five fonts and no hierarchy) into a clean one."], "title": "Graphic design fundamentals"}, {"steps": ["Carousel structure: slide 1 hook (a bold question or promise), slides 2 to 6 the story (steps, before-and-after, tips), last slide payoff and call to action (save, share, follow, visit).", "Before-and-after: a room makeover, a hairstyle, a cleaned-up river bank; consistent angle makes it powerful.", "Simple infographics: one idea, few numbers, clear icons; always credit the data source.", "Thumbnails and covers: a face with emotion, three to five words, high contrast.", "Posters for events and causes: what, when, where, who, how to join - the 5Ws in hierarchy."], "title": "Visual storytelling"}, {"steps": ["Explain why consistency matters - people should recognise your content in a busy feed before seeing your name.", "Brand kit contents: logo or signature mark, two or three colours with codes, two fonts, photo and video style (bright, moody, natural), voice (playful, calm, expert), recurring series ('Cheap Eats Friday'), intro or outro style, and three templates (post, carousel, story).", "Show 'Otieno Shoots' brand kit as an example.", "Demonstrate saving a template in Canva (or similar) and reusing it with new content."], "title": "Content branding and consistency"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["Copyright protects original works - photos, videos, music, designs, writing - from the moment they are created. In Kenya, the Copyright Act sets the rules and the Kenya Copyright Board (KECOBO) administers copyright matters. Owning a copy (downloading a photo) does not give you the right to reuse it.", "To use others' work you need permission or a licence. Sources: your own content, the brief owner's content with permission, Creative Commons works (follow the licence - attribution, non-commercial, no derivatives), and free stock sites under their licence terms. Keep the licence link in your credit log.", "Fair dealing (limited uses such as criticism, review or news reporting) exists in many laws, but it is narrow and not a free pass to use songs, films or photos in your content. When in doubt, do not use it or ask permission.", "Consent: get clear permission before filming or photographing people for content, and written permission (a model release - a simple signed or WhatsApp-confirmed agreement) when the content is for a business or will be used widely. Never post children without their parent's or guardian's consent, and avoid identifying vulnerable people.", "Responsibility: do not spread misinformation (check facts before posting), do not defame (false statements that damage someone's reputation), avoid hate speech and content that incites violence, follow platform community guidelines, disclose paid partnerships ('#ad', 'paid partnership') and AI-generated content.", "Protecting your own work: add a subtle signature or watermark on photos, keep original files, and know you can report stolen content to platforms."], "title": "Copyright and responsible content use"}, {"steps": ["Learners create their content brand kit for their brief (or creator brand) in Canva or on paper.", "They design three pieces using the kit: a social post, an event or promotional poster, and a three to five-slide carousel that tells a story (hook, story, payoff and CTA).", "They start a credit and consent log - every image, music track, font or video not made by them (source, licence, link) and every person who appears (consent obtained, how, date)."], "title": "Design a branded post, poster and carousel"}, {"steps": ["In pairs, learners critique each other's designs with the CRAP checklist and the 3-second test.", "Ask two or three assessment questions, especially about copyright and consent."], "title": "Peer critique and knowledge check"}, {"steps": ["Remind learners that session 7 is the portfolio build - all pieces and logs must be ready.", "Set the homework."], "title": "Wrap-up and homework"}], "facilitator": {"delivery": ["Keep design theory visual; show before-and-after every time.", "Make copyright practical - ask learners to audit the content they used in their session 5 video."], "preparation": ["Prepare the cluttered poster, the example brand kit and templates, and the model release template.", "Read KECOBO's public guidance so you can answer basic questions accurately; do not give legal advice."], "after_session": ["Check credit and consent logs in the portfolio folders.", "Record attendance."], "inclusion_and_safeguarding": ["Consent and images of children are safeguarding issues as well as legal ones; be firm.", "Learners must not use content that sexualises, humiliates or targets anyone.", "Shared devices and low data: learners without a suitable phone shoot and edit in pairs or threes and take turns as camera operator, presenter and editor; plan uploads and downloads for programme Wi-Fi. Never require a paid app, premium template or paid music."]}, "demonstrations": [{"steps": ["Redesign a cluttered poster live by applying contrast, repetition, alignment and proximity."], "title": "Poster redesign"}, {"steps": ["Create a branded template and reuse it for a new post in under two minutes."], "title": "Saving and reusing a template"}], "assessment_guides": [{"guide": "Contrast, Repetition, Alignment, Proximity.", "question": "What do the letters in CRAP stand for?"}, {"guide": "Not without permission or a licence that allows it; downloading does not give the right to reuse.", "question": "You downloaded a photo from Google Images. Can you use it in a client's poster?"}, {"guide": "Written permission from a person to use their image; needed for business or widely used content.", "question": "What is a model release and when do you need one?"}, {"guide": "Colours, fonts, logo or signature, style, voice, templates, recurring series.", "question": "Name three things in a content brand kit."}, {"guide": "Disclose it clearly (for example", "question": "What must you do when content is a paid partnership?"}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"1effa6bc-4a2a-4ea9-8f30-f6d12687d259","session_id":"8a1c572a-22f6-4d92-9408-cf320f22f655","content":{"version": "V13.2", "segments": [{"steps": ["Learners share one hook they noticed in their niche.", "Check that each learner has a shot list and consent from their brief."], "title": "Recap and hooks you found"}, {"steps": ["Demonstrate turning on gridlines (Android and iPhone camera settings). Teach the rule of thirds - place the subject on a line or intersection, not dead centre, unless symmetry is the point.", "Leading lines (a road, a counter, a row of market stalls) draw the eye to the subject; framing (a doorway, a window, leaves) adds depth.", "Angles: eye level for connection; low angle to make the subject look powerful; high angle (top-down) for food and products.", "Clean backgrounds: move the subject or yourself to remove clutter; a plain wall or kanga cloth can make a product pop.", "Camera basics: clean the lens with a soft cloth (phones in pockets get greasy); tap to focus and hold to lock focus and exposure; slide to adjust brightness; portrait mode for people and products; avoid digital zoom - move closer instead; take several shots and pick the best.", "Show good and bad examples of each technique, using photos of Kenyan markets, food and people (with consent)."], "title": "Composition and phone camera basics"}, {"steps": ["Light is the biggest difference between amateur and professional-looking content. Natural light is free.", "Window light: place the subject facing or beside a window, not with the window behind them (that creates a silhouette).", "Time of day: early morning and late afternoon (golden hour) give soft, warm light; midday sun in Kenya is harsh and creates strong shadows - move into open shade.", "Backlight on purpose: for silhouettes or glowing hair, but expose for the face if you want it visible.", "DIY tools: a white manila sheet or foil-covered cardboard as a reflector; a white curtain or bedsheet to soften harsh light; a cheap LED ring light for night filming.", "Demonstrate moving a product from a dark corner to window light and show the difference."], "title": "Lighting"}, {"steps": ["Orientation: vertical (9:16) for TikTok, Reels, Shorts and status; horizontal (16:9) for YouTube. Decide before filming.", "Shot types: wide (where are we), medium (who and what are they doing), close-up (detail and emotion). A good sequence mixes them: wide market, medium vendor arranging tomatoes, close-up hands and a smile.", "B-roll: extra footage that shows what is being talked about (hands working, the street outside, the product). Film more B-roll than you think you need.", "Stability: two hands, elbows tucked in, lean on a wall, use a cheap tripod or a stack of books. Hold each shot steady for at least 5 seconds so you have room to edit.", "Movement: slow pan, push in (walk slowly towards the subject), follow (walk behind someone). Move slowly; fast movement looks shaky.", "Settings: film at 1080p and 30 frames per second as a safe default; check storage before you start."], "title": "Mobile video production"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["People forgive average video but not bad sound. Choose quiet places, away from matatu stages, generators and loud music.", "Get the mic close: the phone or a wired earphone mic about 20 to 30 cm from the speaker's mouth; a cheap lapel mic improves sound a lot.", "Avoid wind (shield the mic, record indoors or behind a wall) and echo (rooms with soft furnishings echo less than empty rooms).", "Always record a 10-second test, listen with earphones, then record."], "title": "Capturing clean sound"}, {"steps": ["In pairs (they help each other), learners complete two tasks. Task 1 - a five-photo set for their brief: one wide, one medium, one close-up detail, one top-down or low angle, one portrait of a person with consent - each using a different composition technique and good light.", "Task 2 - film the clips for their storyboard using the shot list, including at least three B-roll shots and one clean audio clip (a short voice line or interview answer).", "The facilitator circulates and coaches on light, stability and sound. Learners filming off-site for their brief can do task 2 as homework but must shoot practice clips now.", "Remind learners to ask permission before photographing anyone and not to film people who decline, or children without their parent's or guardian's consent."], "title": "Practical shoot"}, {"steps": ["Pairs review each other's best three photos and one clip with the checklist - focus sharp, well lit, composition technique visible, clean background, steady video, clear sound.", "Each learner chooses one shot to reshoot and notes why."], "title": "Peer review of shots"}, {"steps": ["Remind learners to back up their footage (cloud or computer) and to install a free video editing app before session 5.", "Set the homework."], "title": "Wrap-up and homework"}], "facilitator": {"delivery": ["Most of the session should be hands-on; keep each lesson segment practical with a live demonstration.", "Coach individually during the shoot; praise good light and composition loudly so others learn."], "preparation": ["Prepare a product and a simple action for the demonstrations; bring a reflector and a cheap tripod if possible.", "Identify safe, quiet shooting spots near the venue."], "after_session": ["Check that every learner has footage to edit in session 5.", "Record attendance."], "inclusion_and_safeguarding": ["Learners must ask permission before photographing or filming anyone; no filming of children without parental or guardian consent.", "Safety when shooting outdoors - stay in groups, avoid dangerous roads and do not film police operations, military sites or restricted areas.", "Learners with basic phones can still do composition and light exercises; pair them for video.", "Shared devices and low data: learners without a suitable phone shoot and edit in pairs or threes and take turns as camera operator, presenter and editor; plan uploads and downloads for programme Wi-Fi. Never require a paid app, premium template or paid music."]}, "demonstrations": [{"steps": ["Photograph the same product in a dark corner, at a window and with a reflector, and compare."], "title": "Light makes the difference"}, {"steps": ["Film a wide, medium and close-up sequence plus B-roll of a simple action (making chai) and show it back."], "title": "Shot sequence"}, {"steps": ["Record a voice line far away, close up and with a wired earphone mic, and play all three."], "title": "Sound test"}], "assessment_guides": [{"guide": "Divide the frame into thirds horizontally and vertically; place the subject on the lines or intersections.", "question": "Explain the rule of thirds."}, {"guide": "Turn them to face the window or move; expose for the face; use a reflector.", "question": "Your subject is standing with a bright window behind them and their face is dark. What do you do?"}, {"guide": "Wide (context), medium (action), close-up (detail, emotion).", "question": "Name the three basic shot types and what each shows."}, {"guide": "It reduces quality; move closer instead.", "question": "Why should you avoid digital zoom?"}, {"guide": "Quiet location, mic close, wired or lapel mic, shield from wind, test recording.", "question": "Name two ways to improve sound when filming on a phone."}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"20f06154-5f56-4412-b481-990e3f0fa9be","session_id":"f067f3b7-67fc-4a7d-aa5b-33657e3e61b1","content":{"version": "V13.2", "segments": [{"steps": ["Ask four learners to share what customers told them about how they found the business. Write the channels on the board and count them.", "Point out that word of mouth and WhatsApp usually appear often for small Kenyan businesses; this is evidence, not guesswork, and it should shape the campaign."], "title": "Recap and customer answers"}, {"steps": ["Explain why 'everyone' is not a target audience: a small budget spread over everyone reaches no one well. A clear audience makes it easier to choose channels, words and images.", "Teach segmentation with Shiru's Bakes. Segment 1 - working mothers in Ruiru and Juja ordering birthday cakes. Segment 2 - small offices ordering bread and snacks weekly. Segment 3 - university students at nearby campuses buying cupcakes for events. Choose one primary segment for the campaign.", "Build a persona live: 'Mercy, 32, accountant in Juja, two children, orders a cake 4 times a year, budget KES 2,000 to 3,500, scrolls Facebook and WhatsApp status in the evening, worried about late delivery and cakes that look different from the photo, trusts recommendations from other mothers.'", "Explain each persona part and how it changes marketing: her worry about late delivery means the campaign must show on-time delivery proof; her evening scrolling means posting at 7 to 9 pm.", "Warn against stereotypes; personas must come from real conversations and data (the homework answers), not assumptions."], "title": "Target audiences and customer personas"}, {"steps": ["Learners fill the persona template for their brief - name, age, location, situation, goals, problems, budget, buying habits, online habits, objections, what builds trust.", "Every persona must include at least two facts from real customer answers. Learners mark them with a star.", "Swap with a partner, who asks two questions the persona does not yet answer. Learners update it."], "title": "Build your customer persona"}, {"steps": ["Facebook: broad adult audience across Kenya, strong for local community groups, Marketplace and events. Formats - posts, photos, videos, reels, groups, Marketplace listings. Good for - local services, second-hand goods, community organisations, older customers. Tip - join and contribute to local groups (estate, town, university) and follow each group's rules on promotion.", "Instagram: visual, younger urban audience. Formats - feed posts, carousels, reels, stories, highlights. Good for - fashion, food, beauty, photography, events. Tip - highlights for prices, how to order and reviews; a clear bio with a WhatsApp link.", "TikTok: short video and discovery, people can find you even with zero followers. Formats - short videos, trends, sounds, duets, lives. Good for - showing products being made or used, behind the scenes, personality-led brands. Tip - the first 2 seconds decide if people keep watching.", "LinkedIn: professional audience. Formats - posts, articles, company pages. Good for - professional services, B2B, recruitment, NGOs, a learner's own career. Tip - share lessons and results, not hard selling.", "How feeds decide (simplified): platforms show content people are likely to engage with - watch time, saves, shares, comments and how quickly people react. Consistency and relevance beat posting a lot. Explain business or professional accounts and their insights (reach, engagement, audience age and location).", "Quick discussion: which two platforms fit Mercy (the persona)? Facebook and WhatsApp status, maybe Instagram. Which fit a youth photographer in Kisumu? Instagram and TikTok."], "title": "Social media marketing on four platforms"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["Explain that WhatsApp Business is a separate free app for businesses and that it should run on a business number. Do not ask learners to switch their personal number in class.", "Demonstrate on a test phone (or screenshots): business profile (name, category, description, address or service area, hours, email, website or Instagram), catalogue (item photo, name, price in KES, short description), greeting message ('Karibu Shiru's Bakes! Send us the cake size and date and we will reply within 30 minutes'), away message, quick replies (/prices, /delivery, /mpesa), and labels (New order, Paid, Delivered).", "Status and broadcast lists: status is good for daily updates (today's fresh bread); broadcast lists only reach people who have saved your number, which is a good consent signal. Never add people to groups or lists without their agreement, and always offer a way to stop messages ('Reply STOP to stop updates').", "Learners write their own WhatsApp Business plan - profile description, three catalogue items with KES prices, greeting message, away message, three quick replies and three labels. Learners who already run a business number can set it up now."], "title": "Demonstration and practice - WhatsApp Business"}, {"steps": ["In groups of three, each learner completes the platform plan: main platform, support platform, WhatsApp Business role, content formats, posting days and times, and why (linked to the persona).", "Peers check each plan against the persona and challenge anything that does not match (for example TikTok-only for a persona who never uses TikTok).", "Learners add the persona and platform plan to their campaign folder."], "title": "Platform plan for your campaign"}, {"steps": ["Run the assessment questions and discuss the answers."], "title": "Knowledge check"}, {"steps": ["Each learner says their persona's name and main platform in one sentence.", "Set the homework."], "title": "Wrap-up and homework"}], "facilitator": {"delivery": ["Do not teach every platform feature; focus on what each platform is for and what works for small businesses.", "Check that personas are based on real answers. If a learner did not do the homework, they can interview a classmate who fits the persona as a stopgap and must complete real interviews before session 5."], "preparation": ["Install WhatsApp Business on a test phone with a test number, or prepare clear screenshots of every step.", "Prepare examples of real Kenyan business pages on each platform (public pages only) for the platform comparison.", "Print or share the persona and platform plan templates."], "after_session": ["Review personas and platform plans; give written feedback in DIRA LEARN on at least one point per learner.", "Record attendance."], "inclusion_and_safeguarding": ["Learners must not add people to groups or broadcast lists without consent.", "Remind learners not to share personal numbers publicly; recommend a separate business number where possible."]}, "demonstrations": [{"steps": ["Read three real or realistic customer quotes, extract facts and fill the persona template live."], "title": "Building a persona from real answers"}, {"steps": ["Walk through profile, catalogue, greeting, away message, quick replies and labels on a test device or screenshots.", "Show status and a broadcast list with an opt-out line."], "title": "WhatsApp Business set-up"}], "assessment_guides": [{"guide": "Limited budget and time; a specific audience makes messages, channels and timing more effective.", "question": "Why is 'everyone' not a good target audience for a small business?"}, {"guide": "Any four of demographics, situation, goals, problems, budget, buying habits, online habits, objections, trust triggers.", "question": "Name four parts of a customer persona."}, {"guide": "LinkedIn (professional decision-makers), possibly Facebook and WhatsApp for local reach. Reason must refer to the audience.", "question": "Which platform would you choose for a B2B cleaning company and why?"}, {"guide": "Quick replies, greeting and away messages, catalogue, labels.", "question": "Name three WhatsApp Business features that save time."}, {"guide": "Get their agreement (they saved your number or asked for updates) and give a way to stop messages.", "question": "What must you do before adding a customer to a broadcast list or group?"}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"21f19877-3e3a-4e52-84c7-f31c181c868f","session_id":"73a7a9f1-7e68-4ef7-ad69-a6eb5e907a7d","content":{"version": "V13.2", "segments": [{"steps": ["Welcome learners and guests (brief owners, DIRA staff, mentors, employers). Thank brief owners.", "Share the rubric: storytelling and strategy (20%), production quality - photo, video, sound (25%), design and brand consistency (20%), responsible content - credits, consent, honesty (15%), presentation and answers (20%).", "Assign each learner two presenters to give written feedback to."], "title": "Showcase set-up and expectations"}, {"steps": ["Run the screenings with the session 8 room plan in the facilitator instructions: the first six presenters in each room go in this block, each with 3 minutes plus 2 minutes of questions.", "Learners present in order, 3 minutes each plus 2 minutes of questions. Play videos with sound checked in advance.", "Ask at least one question per presenter, such as: 'Why did you open with that shot?', 'What would you change with more time?', 'How did you get consent?', 'What result did this piece get?'", "Score with the rubric and note one strength and one improvement."], "title": "Project presentations and questions - block 1"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["Presenters 7 to 12 in each live room now show their projects and portfolios; check the sound before each video and keep the block 1 timer, rubric and questions.", "In a recorded-questions room, do not replay the recordings (the panel scored them before the session); give each recorded presenter 2 minutes of live questions about their creative project and portfolio.", "Each room's panel hands its completed creative project and portfolio rubric sheets to the room facilitator before the feedback round."], "title": "Project presentations and questions - block 2"}, {"steps": ["Learners give written feedback to their two assigned presenters.", "Facilitator highlights patterns in strong projects - strong hooks, good light and sound, consistent brand, clear credits."], "title": "Feedback round"}, {"steps": ["Creator pitch formula: who you are, what you make and for whom, proof (a piece and its result), the ask. Example: 'I am Wanjiku, a Nyeri content creator. I make short videos that help small cafes get noticed - my last video for a local cafe got 12,000 views and the owner says weekend visits went up. I am looking for two more cafes to work with this month.'", "Sharing your portfolio: a short link, a clean index, and a message that introduces you and the value you offer - not 'please check my page'.", "Pathways: employment (social media assistant, videographer, communications assistant at an NGO or company), freelance briefs, building a creator brand, media houses and production companies. Rates vary; start by agreeing clear deliverables and never paying to get work.", "Professional follow-up: thank brief owners and guests within two days, deliver final files, ask for a testimonial.", "Learners practise their pitch once in pairs."], "title": "Pitching yourself and workplace readiness"}, {"steps": ["Learners complete the 30-day content plan: main goal, pillars, posting rhythm, four weekly actions (for example week 1 publish two portfolio pieces, week 2 pitch three local businesses, week 3 start a recurring series, week 4 review analytics), a measure, an accountability partner and one risk.", "Learners share their goal with their accountability partner."], "title": "30-day content plan"}, {"steps": ["Celebrate each learner's project in one sentence.", "Explain how to submit the portfolio (a restricted-access link or files uploaded in DIRA LEARN, never a public link), creative project and credit and consent log in DIRA LEARN, how results and certificates follow the programme's rules, and how alumni can share paid briefs with each other."], "title": "Celebration and close"}], "facilitator": {"delivery": ["Keep strict time; celebrate creativity and honest reflection.", "Session 8 room plan - Room plan (set in session 7 from the track group size; the session is never extended): up to 12 learners - one room; 13 to 24 - two rooms in parallel; 25 to 36 - three rooms, or two live rooms plus one recorded-questions room. Each live room takes at most 12 presenters: 6 in each 30-minute block, 3 minutes to present and 2 minutes of questions each.", "Every room has a facilitator or briefed co-facilitator (another trainer, a mentor or DIRA staff member who knows the rubric and the safeguarding expectations) and a peer panel of two learners who present in the other block. All rooms use the same rubric.", "Recorded option: learners in a recorded-questions room, and anyone who cannot present live (absence, connection problems, anxiety, or the privacy option), submit a 3-minute recording - video, or a voice note with slides for low data - by the day before session 8. The panel scores it in advance with the same rubric; in session 8 each recorded presenter answers 2 minutes of live questions (12 per block). If more learners need the recorded option than one room can take, the panel sends written questions and the learner answers them in DIRA LEARN.", "Timekeeping: a visible timer with a 30-second warning; stop at 3 minutes. If a block runs late, cut questions to 1 minute - do not extend the session."], "preparation": ["Test video playback with sound for every learner before the session; collect files in advance where possible.", "Invite brief owners and guests; brief guests on respectful questions and safeguarding expectations.", "Confirm the room plan: count the learners in the track group, book the rooms and co-facilitators, brief the peer panels, and publish each room's presenter order and the list of recorded presenters by the end of session 7."], "after_session": ["Enter rubric scores and feedback in DIRA LEARN grading.", "Record attendance."], "inclusion_and_safeguarding": ["Learners who cannot present live can submit a recorded presentation according to the programme's rules.", "Guests must not contact learners privately outside programme channels.", "Shared devices and low data: learners without a suitable phone shoot and edit in pairs or threes and take turns as camera operator, presenter and editor; plan uploads and downloads for programme Wi-Fi. Never require a paid app, premium template or paid music."]}, "demonstrations": [{"steps": ["Before the session, share a recorded 3-minute example presentation as a reference. Do not use showcase time for it."], "title": "Model showcase"}], "assessment_guides": [{"guide": "Use rubric descriptors; honest results and responsible content choices count.", "question": "Presentation scored with the content showcase rubric."}, {"guide": "A specific, reasoned example of each.", "question": "Explain one creative choice and one responsible-content choice in your project."}, {"guide": "Who, what for whom, proof, ask.", "question": "Deliver your creator pitch."}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"2e9f2f72-ff30-4c70-a970-49fe4c3b8002","session_id":"e3e3c255-93c2-456d-98cb-29570193e4eb","content":{"version": "V13.2", "segments": [{"steps": ["Learners share the reach and engagement of the post they published. Note the range and ask what might explain the differences (time, hook, image, audience).", "Say that today is about measuring and improving, not just posting."], "title": "Recap and results from your first post"}, {"steps": ["Organic versus paid: organic posts reach a part of your followers; paid ads reach people chosen by targeting. Paid works best when the offer, content and WhatsApp follow-up are already good - ads amplify, they do not fix a weak offer.", "Boost versus Ads Manager: boosting a post is quick (choose audience, budget, duration); Meta Ads Manager gives more control (objective, placements, multiple ads, testing). Show the boost screen and the Ads Manager campaign structure (campaign - objective; ad set - audience, budget, schedule; ad - creative and copy) using screenshots.", "Objectives: choose the one that matches the campaign goal - for a WhatsApp business, a 'messages' or 'engagement with WhatsApp' style objective is often better than reach. Names change on the platforms, so check the current options in Ads Manager.", "Targeting: location radius (for example 10 km around Ruiru), age, interests, and custom audiences (people who engaged with your page). Too narrow costs more; too broad wastes money.", "Budget: platforms allow small daily budgets; check the current minimum in Ads Manager. Start small (for example a few hundred shillings a day for a few days), test two versions, keep the better one.", "Google Search ads appear for searches with commercial intent ('cake delivery Juja'); you pay per click. Explain briefly; most learners will start with Meta.", "Policies and ethics: ads are reviewed and can be rejected; no misleading claims, before-and-after body images, or restricted products. Paid influencer posts must be disclosed (for example 'ad' or 'paid partnership').", "Payment: ad accounts are paid by card or other methods the platform accepts; the business owner must authorise any spending. Learners must never spend the owner's money without written agreement."], "title": "Introduction to online advertising"}, {"steps": ["SMART campaign objective: 'Get 20 new cake orders through WhatsApp from Ruiru and Juja between 1 and 14 December' rather than 'increase sales'.", "Show the budget sheet (Google Sheets or paper): lines for content (printing, props, sample products for photos), internet data, ads, delivery promotion, incentives (discount cost), and contingency. Use the Shiru's Bakes example totalling about KES 3,000, including KES 1,500 for ads.", "Cost per result: if KES 1,500 of ads brings 30 WhatsApp conversations and 10 orders, cost per conversation = KES 50, cost per order = KES 150. Compare with the profit per order (for example KES 600). If the profit is higher than the cost per order, the ads pay for themselves.", "Zero-budget campaigns are valid - use organic posts, WhatsApp status, broadcast lists, community groups and referral offers. Learners with no ad budget plan time instead of money."], "title": "Campaign planning and budgeting in KES"}, {"steps": ["Teach the measures: reach (unique people who saw it), impressions (times shown), engagement rate (likes, comments, shares, saves divided by reach), clicks, messages started, conversions (orders, bookings), cost per result, return on ad spend (revenue from ads divided by ad cost).", "Link KPIs to objectives: an awareness campaign tracks reach and video views; a sales campaign tracks messages, orders and cost per order. Vanity metrics (likes alone) can mislead.", "Show where to find numbers: Facebook and Instagram professional dashboards and insights, Meta Business Suite, WhatsApp Business (message statistics where available), TikTok analytics for business or creator accounts.", "Track offline and WhatsApp sales: ask every customer 'how did you hear about us?', use a campaign code ('mention CAKE10 for 10% off'), and record orders in a simple tracking sheet (date, customer first name or code, source, amount, campaign code).", "Show the tracking sheet and how to calculate weekly totals. Explain that learning from results ('reels brought more messages than photos, so do more reels') is the real point."], "title": "Marketing analytics and measuring results"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["Learners open the campaign template and fill every section: 1 brief; 2 SMART objective; 3 persona; 4 channels and platform plan; 5 brand mini-kit; 6 key message and offer; 7 two-week content calendar; 8 three finished posts with captions and one WhatsApp broadcast or status message; 9 optional ad plan (objective, audience, creative, budget, duration); 10 budget in KES; 11 KPIs, targets and tracking method; 12 timeline and who does what.", "The facilitator circulates and checks each campaign for consistency - does the persona match the platforms, the message match the brand, the KPI match the objective?", "Learners who finish early create one more asset or a short reel for their campaign."], "title": "Campaign build"}, {"steps": ["In groups of three, each learner presents the campaign in three minutes. Peers use the campaign checklist (clear objective, specific persona, fitting channels, consistent brand, strong hooks, clear CTA, realistic budget, measurable KPIs, consent and honesty) and give two strengths and two improvements.", "Learners make at least one improvement immediately and note the others to finish before session 8."], "title": "Peer testing and revision"}, {"steps": ["Explain the showcase format: three minutes to present (introduce yourself with your self-pitch, the brief, the campaign, any results so far and what you would do next), two minutes of questions. Share the showcase rubric.", "Homework: finish the campaign, run at least one part of it in real life (publish posts or a status campaign with permission) and record the results, prepare a five-slide presentation or a one-page visual."], "title": "Showcase preparation and homework"}], "facilitator": {"delivery": ["Do not spend money or ask learners to spend money in class. Advertising is optional; zero-budget campaigns get the same marks if well planned.", "Spend most of your time circulating during the build; this is where learning is consolidated."], "preparation": ["Prepare Ads Manager and boost screenshots (platform screens change; check them shortly before the session).", "Prepare the campaign template, budget sheet, tracking sheet, checklist and showcase rubric.", "Set the session 8 room plan from the track group size (up to 12 - one room; 13 to 24 - two rooms; 25 to 36 - three rooms, or two live rooms plus a recorded-questions room) and line up co-facilitators and peer panels."], "after_session": ["Review campaigns submitted to DIRA LEARN and flag any that are incomplete before session 8.", "Record attendance."], "inclusion_and_safeguarding": ["Learners must have the business owner's written agreement (a WhatsApp message is enough) before any spending or posting on the business's behalf.", "Campaigns must not target minors or use content involving children without parental consent.", "Consent and privacy: before using an identifiable person (face, voice or name), a photograph of someone, or a real business's name, logo, prices, customer details or results, the learner gets permission from that person or owner - in writing (a WhatsApp message is enough) for anything shown outside the class. Never children. Learners who cannot or do not wish to publish publicly use the private or simulated option, which is assessed with the same rubric and never marked down."]}, "demonstrations": [{"steps": ["Using screenshots, walk through boost options and the campaign, ad set and ad levels. Do not spend money live."], "title": "Ads Manager structure and boosting a post"}, {"steps": ["Fill the budget sheet for Shiru's Bakes and calculate cost per message and per order, and compare with profit per order."], "title": "Budget and cost-per-result calculation"}, {"steps": ["Show a page's insights (prepared screenshots) and explain reach, engagement and messages for one post."], "title": "Reading insights"}], "assessment_guides": [{"guide": "Reach counts unique people; impressions count every time it was shown.", "question": "What is the difference between reach and impressions?"}, {"guide": "KES 200 per order (1,000 / 5). Cost per message is KES 40.", "question": "You spent KES 1,000 on ads, got 25 messages and 5 orders. What is the cost per order?"}, {"guide": "Orders (conversions) and cost per order; messages started as a leading indicator.", "question": "Which KPI fits the objective 'get 20 WhatsApp orders'?"}, {"guide": "Ads only amplify; if the offer or follow-up is weak, more people see a weak experience and money is wasted.", "question": "Why should a business fix its offer and WhatsApp replies before paying for ads?"}, {"guide": "Ask how they heard, campaign codes, tracking sheet, unique offers per channel.", "question": "How can you measure sales that happen offline or on WhatsApp?"}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"32860356-b061-4f7c-8d0f-64c1e5bfea47","session_id":"8d817596-1982-4768-9f6f-509ec448a925","content":{"version": "V13.2", "segments": [{"steps": ["Learners list three routine tasks they do every week and estimate the time each takes (for example replying to customer questions, planning a study timetable, writing reports).", "Say that today they will decide which parts AI or automation can help with, and which parts need a human."], "title": "Recap and time audit"}, {"steps": ["Planning: 'I have these tasks and deadlines; make a realistic plan for the week with two hours a day.' Then adjust it to your real life.", "Summarising and organising: turn messy notes into a structured summary with actions; ask for a to-do list sorted by priority.", "Spreadsheets: ask AI to explain or write a formula ('A Google Sheets formula to total column C where column B says Paid'), then test it on sample data.", "Job searching: tailor a CV summary to a job advert (truthfully), prepare interview practice questions, draft follow-up emails.", "Remind learners - always review, adjust and own the final result."], "title": "AI for productivity and everyday tasks"}, {"steps": ["Customer replies: build an FAQ answer set (prices, delivery, opening hours) with AI from the owner's real information; the owner checks every answer before use.", "Product descriptions: give AI the real features and ask for short, honest descriptions for WhatsApp catalogue and Jumia-style listings.", "Market research: ask AI for questions to ask customers and competitors to look at, then verify with real observation and conversations; AI does not know your local market prices.", "Business documents: quotes, invoices, simple plans and letters - check numbers carefully.", "Where AI should not decide alone: setting prices without real cost data, hiring decisions, deciding who gets credit, medical or legal advice. AI can support thinking; a responsible person decides."], "title": "AI-assisted business activities"}, {"steps": ["Define automation: a rule that does a task automatically. Every automation has a trigger (something happens), an action (what is done) and should have a human check where mistakes matter.", "Everyday examples: WhatsApp Business greeting and away messages (trigger - message received; action - auto-reply); email filters; scheduled social posts; a Google Form that saves answers to a Google Sheet and sends a confirmation email.", "No-code tools such as Zapier, Make or built-in automation in Google and Microsoft tools can connect apps (for example 'new form response, then add a row and notify me'). Explain conceptually; free tiers and features change.", "Demonstrate (or show screenshots of) a Google Form connected to a Sheet for event registrations, and explain the human check (someone reviews registrations daily).", "When automation goes wrong: auto-replies giving wrong prices, messages sent to the wrong list, AI chatbots promising things the business cannot deliver. Rule - automate the routine, keep a human for exceptions and anything involving money, complaints or personal data."], "title": "Introduction to automation"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["Privacy: personal data is any information that identifies a person (name, phone, ID, location, photos, health). Kenya's Data Protection Act 2019 requires personal data to be processed lawfully, fairly and transparently, for clear purposes, and kept secure; people have rights such as being informed and objecting. The Office of the Data Protection Commissioner oversees it.", "In practice: do not paste customers' or classmates' personal data into AI tools; remove names and numbers first (anonymise); check tool settings for chat history and training; use business or education versions with stronger protection if your organisation provides them.", "Bias: AI learns from data that reflects existing inequalities. Examples - image tools showing doctors as men and nurses as women; CV-screening tools that disadvantage certain names or schools; poorer performance in Kiswahili, Sheng and Kenyan local languages than in English. Ask AI for diverse examples and check outputs for stereotypes.", "Limitations: out-of-date knowledge, invented facts, no real understanding of local context, inconsistent answers, and over-reliance (if AI does all your thinking, your skills weaken).", "When not to use AI: confidential matters, emergencies, decisions that seriously affect someone's life, tasks your school or employer forbids, and anything you cannot check."], "title": "Privacy, bias and limitations"}, {"steps": ["Learners choose one routine workflow (their own, or one from their project user - for example a salon's booking enquiries, a youth group's event registration, a student's weekly study routine).", "They map each step and label it: H (human only), AI (AI-assisted with human check), A (automated with human check). They mark where personal data appears and how it is protected.", "They write a reusable prompt set - three to five prompts with placeholders (for example [customer question], [price list]) - and test at least two.", "Partners review the map for privacy risks and missing human checks."], "title": "Workflow map and reusable prompt set"}, {"steps": ["Run the assessment questions and discuss answers."], "title": "Knowledge check"}, {"steps": ["Remind learners that session 7 is the project build - bring the project plan, prompt library and any materials.", "Set the homework."], "title": "Wrap-up and homework"}], "facilitator": {"delivery": ["Keep automation conceptual and safe - learners should not connect real customer accounts or business data in class.", "Encourage learners to choose workflows from their real lives or project users."], "preparation": ["Prepare a sample spreadsheet, a sample anonymised customer message list and a working Google Form and Sheet.", "Read the summary of the Kenya Data Protection Act 2019 from the Office of the Data Protection Commissioner so you can answer basic questions; do not give legal advice."], "after_session": ["Review workflow maps for privacy issues before learners use them in their projects.", "Record attendance."], "inclusion_and_safeguarding": ["Learners must not use real personal data in exercises; use anonymised or invented data.", "Bias discussions can touch on identity; keep them respectful and evidence-based.", "Shared devices and low data: pair or group learners on one device and rotate the typing role each task; learners without a device or data follow the shared screen and record their work on paper or later on programme Wi-Fi. Never require a paid tool or plan, or an account that needs personal data the learner does not want to give."]}, "demonstrations": [{"steps": ["Ask AI for a formula, paste it into a sheet with sample data and test it, fixing any error."], "title": "AI spreadsheet formula"}, {"steps": ["Show a Google Form linked to a Sheet with an email notification, and the human review step."], "title": "Form-to-sheet automation"}, {"steps": ["Take a sample customer message list and remove names and numbers before using AI to categorise the questions."], "title": "Anonymising data"}], "assessment_guides": [{"guide": "Trigger, action, human check.", "question": "What are the three parts of an automation?"}, {"guide": "Hiring, credit, pricing without data, medical, legal, safeguarding decisions.", "question": "Name two tasks where AI should not make the final decision."}, {"guide": "Lawful, fair and transparent processing for a clear purpose, limited to what is needed, kept secure; people have rights over their data.", "question": "What does the Kenya Data Protection Act 2019 require when handling personal data?"}, {"guide": "Stereotyped images or unfair screening; ask for diversity, check outputs, use human review, use better data.", "question": "Give one example of AI bias and how to reduce it."}, {"guide": "Remove or replace names, numbers, IDs, addresses and any detail that identifies a person.", "question": "How do you anonymise data before using AI?"}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"3b8c4341-296c-489b-ae22-8cc812c35bad","session_id":"6c899251-1167-4d98-b406-bd7762ae75a7","content":{"version": "V13.2", "segments": [{"steps": ["Ask learners what they had to check or change in their task logs. Group the answers (wrong facts, generic tone, missing local detail, too long).", "Say that today they learn to get better outputs (prompting) and to catch problems (fact-checking)."], "title": "Recap and task log review"}, {"steps": ["Teach RTCF. Role - who the AI should act as ('You are a careers adviser in Kenya'). Task - exactly what to do ('Write three bullet points for a CV'). Context - the details it needs ('for Amina, 22, diploma in hospitality from Mombasa, two years of part-time waitressing'). Format - how the answer should look ('three bullets, each under 15 words, British English').", "Add constraints and examples: tone, audience, length, language (English, Kiswahili), what to avoid. Give an example of the style you want; AI copies examples well.", "Prompt patterns: (1) Step by step - 'Explain step by step'; (2) Ask me questions first - 'Before you answer, ask me up to five questions you need'; (3) Critique and improve - 'Here is my draft; list three weaknesses, then rewrite it'; (4) Compare options - 'Give three options with pros and cons in a table'; (5) Role-play - 'Act as a tough interviewer for a bank teller job and ask me one question at a time'.", "Iteration: the first answer is a draft. Follow up - 'shorter', 'more local examples', 'simpler words', 'make it sound like a 20-year-old wrote it, not a robot'.", "Show a weak and a strong prompt side by side with their outputs."], "title": "Prompt engineering - framework and patterns"}, {"steps": ["Learners get four weak prompts ('write about farming', 'make a CV', 'business ideas', 'explain taxes') and rewrite each using RTCF for a specific Kenyan situation.", "They run their weak and strong versions and rate both outputs from 1 to 5, noting why the strong one is better.", "Learners save their best three prompts in a prompt library (document or note) with the purpose, the prompt text and tips.", "Pairs swap one prompt and test each other's; they suggest one improvement."], "title": "Prompt lab"}, {"steps": ["Name the tools for today: free tiers of ChatGPT, Gemini, Copilot or Claude, and Perplexity for cited answers - or Duck.ai, which needs no account at all. Everyone can do every exercise with Duck.ai or on the shared screen.", "AI as a tutor: 'Explain [topic] as if I am in Form Four, then give me five quiz questions, then mark my answers.' Show this live with a topic like compound interest or photosynthesis.", "Summarising: only paste texts you are allowed to share (public documents, your own notes). Ask for a summary plus 'what is missing or uncertain?'.", "Research planning: ask AI to suggest research questions, keywords and types of sources, then do the actual research with search engines and reliable sources.", "Research tools that show sources (some assistants can search the web and cite pages) are more checkable, but the sources must still be opened and read - AI sometimes cites pages that do not say what it claims, or invents references entirely.", "Learning integrity: using AI to understand is good; submitting AI work as your own understanding is not. Follow your institution's rules."], "title": "AI for research and learning"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["Ask AI a factual question with Kenyan specifics (for example 'What are the requirements to register a business name in Kenya and how much does it cost?'). Read the answer.", "Apply the routine. Stop - do not share yet. Identify the claims (requirements, costs, process). Lateral reading - search each claim and open official sources (eCitizen Business Registration Service pages for business names; KRA for tax; Kenya Law for laws; KNBS for statistics). Compare. Mark each claim as confirmed, wrong or not found.", "Show a fake reference: ask the AI for 'three academic references on youth unemployment in Kenya' and check whether each actually exists (search the exact title). Explain that invented references are common.", "Show the evaluation checklist - accuracy, relevance, completeness, up to date, bias or one-sidedness, appropriate for the audience.", "Learners apply the routine to one AI answer from their own task log or prompt lab and record the result."], "title": "Demonstration and practice - fact-checking AI outputs"}, {"steps": ["Learners choose a question linked to their final project idea (for example 'What support exists for young farmers in Nakuru County?' or 'What do small shops in my area struggle with online?').", "They use AI to plan the question and draft a 200-word brief, then verify at least five claims with real sources, correcting or removing anything unverified.", "The final brief lists sources (title and link) beside each claim and ends with the AI disclosure line."], "title": "Verified research brief"}, {"steps": ["Run the assessment questions and discuss answers."], "title": "Knowledge check"}, {"steps": ["Ask learners to name their best prompt pattern so far.", "Set the homework."], "title": "Wrap-up and homework"}], "facilitator": {"delivery": ["Have learners type and test, not just listen; the prompt lab is the core of the session.", "When fact-checking, verify live even if it is slow - learners must see the effort it takes."], "preparation": ["Prepare weak prompts, a factual question with Kenyan specifics and the fact-checking routine slide.", "Check that the official websites load on the venue internet; prepare screenshots as a backup.", "In the week of the session, test on the venue network which free AI tools work without signing in (start with Duck.ai), and tell learners in advance that no account is required to take part."], "after_session": ["Give feedback on research briefs, especially the quality of sources.", "Record attendance."], "inclusion_and_safeguarding": ["Remind learners to paste only public or their own content when summarising.", "Health, legal and financial AI answers must always be checked with qualified sources; say so explicitly.", "Shared devices and low data: pair or group learners on one device and rotate the typing role each task; learners without a device or data follow the shared screen and record their work on paper or later on programme Wi-Fi. Never require a paid tool or plan, or an account that needs personal data the learner does not want to give.", "No learner is required to create an AI account. Learners who choose to sign up use a programme-only email if they prefer, and never their ID number."]}, "demonstrations": [{"steps": ["Run a weak prompt, then the RTCF version, and compare outputs aloud."], "title": "Weak versus strong prompt"}, {"steps": ["Verify an AI answer claim by claim against official sources and test whether AI-provided references exist."], "title": "Fact-checking routine and fake references"}], "assessment_guides": [{"guide": "Role, Task, Context, Format.", "question": "What do the letters RTCF stand for?"}, {"guide": "Should add role, specific business, location, audience, length and format.", "question": "Improve this prompt - 'make me a business plan'."}, {"guide": "Checking a claim by opening other reliable sources rather than relying on the one answer.", "question": "What is lateral reading?"}, {"guide": "Search the exact title and author, find the original, confirm it exists and says what was claimed.", "question": "An AI gives you a reference to a report. How do you check it?"}, {"guide": "Accuracy, relevance, completeness, currency, bias, suitability for audience.", "question": "Name four things to check in an AI output."}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"3f6c4dfd-4ad5-4c9f-a172-4ae358911cd9","session_id":"b46fd49d-d091-4eeb-aab7-10373005b48a","content":{"version": "V13.2", "segments": [{"steps": ["Learners state their brief in one sentence: 'I am building [solution] for [user] to [solve problem], and it works if [success test].'", "Project types to choose from: a study resource pack (explanations, quizzes, summaries) for a group of learners; a customer-service prompt kit and FAQ for a small business; an AI-assisted information or marketing pack for a community group; a simple automated workflow (form, sheet, AI-drafted replies with human review)."], "title": "Project check-in"}, {"steps": ["Explain the project design canvas: user and problem; what AI does; what the human does; tools; prompts; data used and how it is protected; risks and checks; success test.", "Walk through a worked example - 'Customer reply kit for a Kitengela hardware shop': AI drafts answers from the owner's price list and policies; the owner approves answers; quick replies are saved in WhatsApp Business; success test - the owner answers 10 common questions in under 10 minutes with no wrong information.", "Learners complete their canvas in 8 minutes; the facilitator checks the success tests are specific."], "title": "Designing your solution"}, {"steps": ["Learners build the solution using their tools and prompt library. They document the final prompt set, example inputs and outputs, and short instructions for the user.", "Checkpoint at 20 minutes: each learner shows the facilitator one working output and one check they have done.", "The facilitator circulates, unblocking technical problems and asking 'how do you know this is correct?' and 'where is the human check?'.", "Learners who finish early add a second feature or improve the user instructions."], "title": "Build"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["Learners score their solution against the AI quality checklist (1 to 3 each): accuracy, usefulness, clarity, safety and appropriateness, privacy, bias and fairness, disclosure. Anything scoring 1 must be fixed.", "Learners test the solution with a real user (by phone, in person or via WhatsApp) or, if not possible during the session, with a peer playing the user, and record what worked, what confused them and what they would change. Real user testing must be completed before session 8."], "title": "Evaluate and user-test"}, {"steps": ["Learners fix the top two problems from the checklist and test.", "They prepare the demo: self-pitch introduction (15 seconds), the problem and user, a live or recorded demonstration of the solution, before and after (time saved or quality improved), checks and responsible choices, user feedback, what next. Ends with the disclosure line.", "Partners watch a 1-minute run-through and give one improvement."], "title": "Revise and prepare the demonstration"}, {"steps": ["Explain the showcase format (3 minutes demo, 2 minutes questions), the rubric and the submission (solution files, prompt set, checklist, user feedback, disclosure).", "Set the homework."], "title": "Showcase briefing and homework"}], "facilitator": {"delivery": ["Protect the 45-minute build time; keep instructions short.", "Push for real users and real problems; a polished solution nobody needs scores lower than a simple useful one."], "preparation": ["Review project plans before the session and prepare to unblock common technical issues.", "Prepare the design canvas, checklist and demo template.", "Set the session 8 room plan from the track group size (up to 12 - one room; 13 to 24 - two rooms; 25 to 36 - three rooms, or two live rooms plus a recorded-questions room) and line up co-facilitators and peer panels."], "after_session": ["Check every learner has arranged a real user test before session 8.", "Record attendance."], "inclusion_and_safeguarding": ["Projects must not use real personal data without consent; anonymise or use invented data.", "Projects giving health, legal or financial information must be checked by a qualified person before anyone relies on them, and must say so.", "Consent and privacy: before using an identifiable person (face, voice or name), a photograph of someone, or a real business's name, logo, prices, customer details or results, the learner gets permission from that person or owner - in writing (a WhatsApp message is enough) for anything shown outside the class. Never children. Learners who cannot or do not wish to publish publicly use the private or simulated option, which is assessed with the same rubric and never marked down.", "Shared devices and low data: pair or group learners on one device and rotate the typing role each task; learners without a device or data follow the shared screen and record their work on paper or later on programme Wi-Fi. Never require a paid tool or plan, or an account that needs personal data the learner does not want to give."]}, "demonstrations": [{"steps": ["Walk through the completed design canvas for the hardware shop reply kit and show two outputs with the owner's corrections."], "title": "Worked project example"}], "assessment_guides": [{"guide": "Each criterion scored; items scored 1 fixed or explained.", "question": "AI quality checklist completed for the solution."}, {"guide": "A specific, observable test with an honest result.", "question": "What is your success test, and did the solution pass?"}, {"guide": "At points involving facts, money, personal data or decisions affecting people.", "question": "Where is the human check in your solution, and why there?"}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"5019ae78-b077-488d-8a06-73f05479a570","session_id":"a123acb1-7333-44ae-92fb-d190c9ebd22c","content":{"version": "V13.2", "segments": [{"steps": ["Show the journey: S3 opportunity spotting, S4 value proposition and business model, S5 money - costing, pricing and cash flow, S6 marketing, customer experience and sales, S7 test and pitch, S8 pitch showcase.", "Explain the final project - a tested business concept and a 3-minute pitch. Say that the goal is evidence, not a perfect plan.", "Ask learners to share in one sentence a business they admire in their area and why."], "title": "Welcome to Entrepreneurship & Business and track overview"}, {"steps": ["Define an opportunity: a problem or need that enough people have, that they would pay to solve, and that you can realistically solve. An idea is a possible solution; an opportunity is the problem plus a market.", "Sources of opportunities: (1) problems people complain about (water shortages, unreliable deliveries, expensive school uniforms); (2) trends (mobile money, online shopping, solar, recycling, urban farming, a growing youth population); (3) your skills and networks (you can cook, fix phones, know farmers); (4) gaps (no laundry service near a university hostel).", "Kenyan examples: a young person in Nakuru who saw students struggling to dry clothes in the rainy season and started a laundry pick-up service; a group in Machakos turning mango waste into dried mango snacks; a Kibera youth group collecting plastic for recycling companies.", "Opportunity filter - ask four questions: Is the problem real and frequent? Do people pay to solve it today? Can I reach these customers? Can I start small with what I have?", "Learners list three problems they have seen this week in their community."], "title": "Identifying business opportunities"}, {"steps": ["The job: what the customer is trying to get done. A mother buying a school uniform is not buying cloth; she is getting her child ready for school on time, looking smart, within budget.", "Pains: what annoys, costs or worries them (long queues, poor quality, prices going up, unreliable sellers). Gains: what would delight them (durability, delivery, paying in instalments with M-Pesa).", "How they solve it today: the current alternative is your real competition - even if it is 'doing nothing' or 'asking a cousin'.", "Frequency, intensity and willingness to pay: a problem that happens daily and hurts a lot is a better opportunity than one that happens once a year and is mildly annoying.", "Assumptions versus evidence: 'students will pay KES 100 for laundry pick-up' is an assumption until real students say they have paid for similar services or actually pay. List assumptions and mark the riskiest - the one that would kill the idea if wrong.", "Work through one learner's problem as a group, mapping job, pains, gains and assumptions on the board."], "title": "Understanding customer problems"}, {"steps": ["Primary research: observe (count customers at a competitor's stall at different times), interview (ten conversations teach more than a hundred opinions online), short surveys (a Google Form shared in a relevant WhatsApp group, with the admin's permission).", "Secondary research: the Kenya National Bureau of Statistics (KNBS) publishes population and economic data; county governments publish plans and statistics; industry and news reports give trends. Always note the source and date.", "Target market and early adopters: the target market is the specific group you serve first; early adopters are the people with the problem most urgently who are already trying to solve it - they will try something new first.", "Rough market size: how many potential customers in your area, how often they buy, and how much they spend. Example - 2,000 students in nearby hostels, 30% send laundry out, twice a month, KES 150 each.", "Competition and alternatives: who else solves the problem and how; what you could do differently."], "title": "Market research and target markets"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["Role-play a bad interview with a co-facilitator or volunteer: 'Would you buy my amazing juice? It is healthy and cheap, don't you think?' Point out leading questions, talking about the idea, and asking about the future.", "Role-play a good interview: 'Tell me about the last time you bought juice or a snack in the afternoon. Where? How much? What did you like or dislike? What else did you consider?' Point out questions about past behaviour, listening more than talking, and not pitching.", "Share the interview guide template: warm-up, the problem (last time it happened), current solution, pains, spending, what an ideal solution would do, permission to follow up. Ten questions maximum."], "title": "Demonstration - good and bad customer interviews"}, {"steps": ["Learners choose the opportunity they will develop for the track (from their three problems or an existing idea) and write an interview guide of eight to ten questions.", "In pairs, learners interview each other (5 minutes each) as if the partner were a potential customer. The interviewer notes what they learned; the partner gives feedback on any leading questions.", "Learners revise their guide based on the feedback."], "title": "Interview guide and practice interviews"}, {"steps": ["Learners complete the one-page opportunity statement: the problem, who has it (target market and early adopters), how they solve it today, why that is not good enough, the opportunity, rough market size, top three assumptions (riskiest first), and how they will gather evidence this week.", "The facilitator checks a few statements and gives quick feedback on specificity."], "title": "Opportunity statement"}, {"steps": ["Ask two learners to read their opportunity sentence.", "Set the homework - at least five real interviews before session 4."], "title": "Wrap-up and homework"}], "facilitator": {"delivery": ["Learners often fall in love with their idea; keep bringing them back to the customer's problem and evidence.", "Encourage learners to work on ideas they can test cheaply in the next three weeks."], "preparation": ["Prepare the interview guide and opportunity statement templates and the role-play script.", "Arrange a co-facilitator or volunteer for the role-play."], "after_session": ["Check opportunity statements and give each learner one question to explore in interviews.", "Record attendance."], "inclusion_and_safeguarding": ["Interviews in the community must be safe - interview in public places or by phone, never alone at a stranger's home, and tell someone where you are.", "Do not interview children for business research.", "Consent and privacy: before using an identifiable person (face, voice or name), a photograph of someone, or a real business's name, logo, prices, customer details or results, the learner gets permission from that person or owner - in writing (a WhatsApp message is enough) for anything shown outside the class. Never children. Learners who cannot or do not wish to publish publicly use the private or simulated option, which is assessed with the same rubric and never marked down."]}, "demonstrations": [{"steps": ["Role-play a leading interview and a good one, then debrief the differences."], "title": "Bad versus good customer interview"}], "assessment_guides": [{"guide": "An idea is a possible solution; an opportunity is a real problem with customers willing to pay that you can reach.", "question": "What is the difference between an idea and an opportunity?"}, {"guide": "Ask about past behaviour, for example 'Tell me about the last time you bought a drink in the afternoon.'", "question": "Rewrite this leading question - 'Would you buy my cheap healthy juice?'"}, {"guide": "The assumption that would end the idea if wrong (often willingness to pay or reaching customers).", "question": "What is the riskiest assumption in your idea?"}, {"guide": "Primary - interviews, observation, surveys. Secondary - KNBS data, county reports, news, industry reports.", "question": "Name one primary and one secondary research method."}, {"guide": "Customers who feel the problem most and are already looking for solutions; they try new things first.", "question": "Who are early adopters?"}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"56351ef3-15e2-4cd8-ad12-b8dfeaddeb4e","session_id":"caff2418-786e-415b-8812-bb2845d1a0ff","content":{"version": "V13.2", "segments": [{"steps": ["Welcome learners and guests (users, DIRA staff, mentors, employers). Thank users who tested solutions.", "Share the rubric: problem and user (15%), solution works and is useful (25%), evaluation and human checks (25%), privacy, fairness and disclosure (20%), presentation and answers (15%).", "Etiquette and peer-feedback assignments: each learner gives written feedback to two presenters."], "title": "Showcase set-up and expectations"}, {"steps": ["Run the demonstrations with the session 8 room plan in the facilitator instructions: the first six demonstrators in each room go in this block, each with 3 minutes plus 2 minutes of questions.", "Learners demonstrate in order, 3 minutes each plus 2 minutes of questions. Recorded demos are allowed if the internet fails.", "Ask at least one question per presenter, such as: 'Show me an output that was wrong and how you caught it', 'What personal data does this touch and how is it protected?', 'What would happen if the AI tool changed or became paid?', 'Would your user keep using it? Why?'", "Score with the rubric and note one strength and one improvement."], "title": "Demonstrations and questions - block 1"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["The remaining demonstrators in each live room (7 to 12) go now, with the same timer, rubric and question approach as block 1.", "In a recorded-questions room, do not replay the recordings (the panel scored them before the session); give each recorded presenter 2 minutes of live questions about their AI solution.", "Each room's panel hands its completed AI solution rubric sheets to the room facilitator before the feedback round."], "title": "Demonstrations and questions - block 2"}, {"steps": ["Learners give their written feedback to their two assigned presenters.", "Reflection: learners revisit the group AI use code from session 3. Which rules were easy to follow, which were hard, and would they change any?", "Facilitator summarises patterns in strong projects (real user, clear human checks, honest evaluation)."], "title": "Feedback round and responsible AI reflection"}, {"steps": ["Case study format: problem, user, what I built, how I checked it, results and feedback, what I learned. Add screenshots and the disclosure.", "Pitch formula with proof: 'I am Faith from Kericho. I use AI tools responsibly to save time on routine work. I built a reply kit for a hardware shop that cut answering time from 30 to 10 minutes with zero wrong prices. I am looking for an administrative or digital assistant role.'", "Employers value people who can use AI and check it - prompting, verification, workflow design and honesty about AI use. Never claim AI work as entirely your own; explain your role.", "Pathways: office and administrative roles, customer service, digital assistants, freelance support work (Ajira Digital provides information on online work), and using AI in your own business. Avoid scams promising easy money from 'AI jobs' for a fee.", "Learners practise their pitch once in pairs."], "title": "Pitching yourself and workplace readiness"}, {"steps": ["Learners complete the 30-day plan: main goal, four weekly actions (for example week 1 finish the case study, week 2 offer the solution to two more users, week 3 learn one new AI tool safely, week 4 apply for two roles), a measure of success, an accountability partner and one risk with a plan.", "Learners share their goal with their accountability partner."], "title": "30-day action plan"}, {"steps": ["Celebrate each learner's solution in one sentence.", "Explain how to submit the final AI solution and its verification note in DIRA LEARN, how results and certificates follow the programme's rules, and how alumni can keep sharing useful prompts and tools."], "title": "Celebration and close"}], "facilitator": {"delivery": ["Keep strict time; prioritise questions about checking and responsibility.", "Session 8 room plan - Room plan (set in session 7 from the track group size; the session is never extended): up to 12 learners - one room; 13 to 24 - two rooms in parallel; 25 to 36 - three rooms, or two live rooms plus one recorded-questions room. Each live room takes at most 12 presenters: 6 in each 30-minute block, 3 minutes to present and 2 minutes of questions each.", "Every room has a facilitator or briefed co-facilitator (another trainer, a mentor or DIRA staff member who knows the rubric and the safeguarding expectations) and a peer panel of two learners who present in the other block. All rooms use the same rubric.", "Recorded option: learners in a recorded-questions room, and anyone who cannot present live (absence, connection problems, anxiety, or the privacy option), submit a 3-minute recording - video, or a voice note with slides for low data - by the day before session 8. The panel scores it in advance with the same rubric; in session 8 each recorded presenter answers 2 minutes of live questions (12 per block). If more learners need the recorded option than one room can take, the panel sends written questions and the learner answers them in DIRA LEARN.", "Timekeeping: a visible timer with a 30-second warning; stop at 3 minutes. If a block runs late, cut questions to 1 minute - do not extend the session."], "preparation": ["Publish the demo order and test screen sharing; ask learners to have a recorded backup.", "Invite users and guests; brief guests on respectful questions and safeguarding expectations.", "Confirm the room plan: count the learners in the track group, book the rooms and co-facilitators, brief the peer panels, and publish each room's presenter order and the list of recorded presenters by the end of session 7."], "after_session": ["Enter rubric scores and feedback in DIRA LEARN grading.", "Record attendance."], "inclusion_and_safeguarding": ["Learners unable to present live can submit a recorded demo according to the programme's rules.", "Guests must not contact learners privately outside programme channels.", "Shared devices and low data: pair or group learners on one device and rotate the typing role each task; learners without a device or data follow the shared screen and record their work on paper or later on programme Wi-Fi. Never require a paid tool or plan, or an account that needs personal data the learner does not want to give."]}, "demonstrations": [{"steps": ["Before the session, share a recorded 3-minute example demo (the hardware shop reply kit) as a reference. Do not use showcase time for it."], "title": "Model demonstration"}], "assessment_guides": [{"guide": "Use rubric descriptors; honest evaluation and responsible choices score highly even if the solution is simple.", "question": "Demonstration scored with the AI showcase rubric."}, {"guide": "A concrete example with the checking method.", "question": "Show one AI output that was wrong and explain how you caught and fixed it."}, {"guide": "Who, skill, proof with a number or result, ask; honest about AI's role.", "question": "Deliver your pitch with your project as proof."}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"59c9171f-4c26-4b11-9a92-2866f2e10d28","session_id":"6e1a25df-015a-49d9-9c8b-2940fca1a883","content":{"version": "V13.2", "segments": [{"steps": ["Learners share what happened when they used their sales script with real customers.", "Introduce the idea of testing - evidence beats opinions, including your own."], "title": "Recap and sales script results"}, {"steps": ["Minimum viable product (MVP): the simplest version of your offer that lets you learn whether customers really want it - for example ten bottles of juice sold at an office, not a whole juice bar.", "Test types: pre-orders (take orders and deposits before producing); pilots (serve five customers for a week); sample sales (sell a small batch at a market day); smoke tests (post the offer on WhatsApp status or a catalogue and count real enquiries before you have stock - be honest that it is a pre-launch).", "Success criterion before testing: 'If at least 8 out of 20 office workers pre-order at KES 80, the willingness-to-pay assumption is supported.' Decide before you look at results so you do not fool yourself.", "Reading results honestly and deciding: continue (evidence supports), change (pivot the customer, price or offer), or stop (save your money and time). Changing or stopping is learning, not failure.", "Ethics: never take money for something you cannot deliver; refund pre-orders if you stop."], "title": "Testing business ideas"}, {"steps": ["Learners complete the test card: riskiest assumption, test type, what they will do, who with, when, cost, success criterion, and how they will record results.", "Partners check that the test is cheap, quick (within one week), ethical and has a clear number as the success criterion.", "Learners who already ran a test (homework) record the results and decision instead."], "title": "Design your test"}, {"steps": ["Legal basics as next steps (not required to test): business name registration through the eCitizen Business Registration Service, a KRA PIN, county single business permits, and any sector licences (food handling for food businesses). Requirements and fees change - check the official websites.", "Funding options: own savings, family and friends (agree terms in writing), chamas and SACCOs, government youth and enterprise funds, grants and youth business competitions, and later investors. Match the funding to the need and repay what you borrow.", "Milestones: the next three steps with dates (for example 'first 20 paying customers by end of January').", "Learners finish their one-page plan."], "title": "Completing the lean business plan"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["Pitch structure for 3 minutes: (1) hook - a story or a striking fact about the problem (20 seconds); (2) problem and customer (30 seconds); (3) solution and value proposition (30 seconds); (4) evidence - interviews, test results, pre-orders (30 seconds); (5) business model and key numbers - price, variable and fully allocated unit cost, contribution per unit, break-even (30 seconds); (6) team - you and why you (15 seconds); (7) the ask and next step (25 seconds).", "The ask: what you want from the audience - advice, a first customer, a partner, a space, a small grant. Make it specific.", "Delivery: stand or sit tall, speak slowly, look at the audience or camera, use one simple visual or slide per part, practise with a timer.", "Show a 3-minute example pitch for Fresh Fold (recorded or live by the facilitator)."], "title": "Pitch structure"}, {"steps": ["Learners write their pitch using the template and create up to five simple slides or a one-page visual.", "They include at least one piece of real evidence (interview quotes, numbers, test results) and their key numbers from session 5.", "They practise once alone with a timer."], "title": "Build your pitch"}, {"steps": ["In groups of three, each learner pitches in 3 minutes. Peers use the pitch rubric (clear problem, credible solution, real evidence, sensible numbers, specific ask, delivery) and give two strengths and two improvements.", "Learners revise their assumptions list and pitch based on the feedback."], "title": "Peer pitch review"}], "facilitator": {"delivery": ["Keep pushing for evidence; a pitch without evidence is a wish.", "Learners whose test showed the idea does not work should be praised and helped to pitch what they learned and their changed idea."], "preparation": ["Prepare the test card, lean plan and pitch templates, the pitch rubric and the example pitch.", "Check current official information on business registration and permits if you plan to mention specifics.", "Set the session 8 room plan from the track group size (up to 12 - one room; 13 to 24 - two rooms; 25 to 36 - three rooms, or two live rooms plus a recorded-questions room) and line up co-facilitators and peer panels."], "after_session": ["Check every learner has a pitch draft and a test plan; message those at risk.", "Record attendance."], "inclusion_and_safeguarding": ["Tests must be ethical - no taking money for things learners cannot deliver; refunds if they stop.", "Learners must not borrow money to run a test.", "Consent and privacy: before using an identifiable person (face, voice or name), a photograph of someone, or a real business's name, logo, prices, customer details or results, the learner gets permission from that person or owner - in writing (a WhatsApp message is enough) for anything shown outside the class. Never children. Learners who cannot or do not wish to publish publicly use the private or simulated option, which is assessed with the same rubric and never marked down."]}, "demonstrations": [{"steps": ["Deliver or play a 3-minute Fresh Fold pitch and point out each part of the structure."], "title": "Example pitch"}], "assessment_guides": [{"guide": "The simplest version of an offer that lets you learn whether customers want it.", "question": "What is a minimum viable product?"}, {"guide": "To avoid interpreting results to fit what you hoped.", "question": "Why set a success criterion before testing?"}, {"guide": "Any three of hook, problem, solution, evidence, model and numbers, team, ask.", "question": "Name three parts of a business pitch."}, {"guide": "Refund it.", "question": "What should you do with pre-order money if you decide to stop?"}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"5e60b12c-552a-4bb3-a578-cd89575c1832","session_id":"1f4e6189-e10c-41dc-9a45-1a32b4ea62ba","content":{"version": "V13.2", "segments": [{"steps": ["Welcome learners to the track. Show the six-session journey on one slide: S3 foundations and presence, S4 audiences, social media and WhatsApp Business, S5 brand, content plan and graphics, S6 copy, conversion and search, S7 ads, budget, measurement and campaign build, S8 showcase.", "Show a one-slide example of a finished campaign for a fictional business, 'Shiru's Bakes' (a home bakery in Ruiru selling cakes and bread on WhatsApp and Instagram): objective, persona, three posts, a KES 1,000 budget and results. Say: by session 8 you will have one like this for a real business.", "Ask learners to share in the chat or aloud one business they buy from because of something they saw online."], "title": "Welcome to Digital Marketing and track overview"}, {"steps": ["Define it: digital marketing is using online channels - social media, WhatsApp, search, marketplaces, SMS and email - to help the right people find, trust, choose and return to a business. Selling is the moment of purchase; marketing is everything that makes that moment more likely.", "Draw the customer journey with the Shiru's Bakes example. Awareness - a neighbour shares her cake photo on WhatsApp status. Consideration - the customer checks Instagram for prices and reviews. Conversion - orders on WhatsApp and pays with M-Pesa. Loyalty - gets a thank-you message and a birthday discount next year and refers a friend.", "Explain owned, earned and paid channels with examples. Owned - the business's own Instagram, WhatsApp Business, Google Business Profile, website. Earned - reviews, shares, customers tagging the business, a local blog mention. Paid - boosted posts, Meta or Google ads, paying a micro-influencer. Most small Kenyan businesses start owned and earned, then add a little paid.", "Tour the main channels quickly: Facebook, Instagram, TikTok, LinkedIn, WhatsApp Business, Google Search and Maps (Google Business Profile), marketplaces (Jumia, Kilimall, Facebook Marketplace), SMS and email. One line each on who uses it and what it is good for. Say that the next sessions go deeper into each.", "Strategy in one sentence: right message, right people, right channel, right time, with a clear action. Ask: which channels would a mama mboga in Kawangware use, and which would a Nairobi graphic designer use? Why different?"], "title": "What digital marketing is, the customer journey and channels"}, {"steps": ["Explain the digital footprint. Active - what you post, comment, like and share. Passive - what others post about you, tags, reviews, location data, search results. Both stay for a long time and screenshots last forever.", "Explain why it matters: employers and clients search candidates; customers read reviews before buying. A single rude reply to a complaint can travel further than ten good posts.", "Reputation rules for a business: respond to every review (good or bad) within a day, thank publicly, solve privately, never argue or reveal a customer's personal details, fix the real problem, and ask happy customers for reviews.", "Teach the review reply model ACE - Acknowledge ('Thank you for telling us, we are sorry your order was late'), Correct or explain briefly without excuses ('our rider had a breakdown'), Engage offline ('please WhatsApp us on our business number so we can make it right').", "Privacy and safety: business accounts should use a business number, not a personal one; do not post customers' faces, children or home locations without consent; under Kenya's Data Protection Act 2019, customer data such as phone numbers must be collected and used fairly and for a clear purpose."], "title": "Digital footprint and online reputation"}, {"steps": ["Search a fictional or consenting local business name on Google and social media (prepare screenshots in case of poor connection). Score it with the presence checklist: name consistent, clear photo or logo, bio says what and where, contact and payment details, opening hours, recent posts, reviews, replies to reviews.", "Show a fictional one-star review: 'Waited 2 hours for my cake and it was the wrong flavour. Never again.' Write the ACE reply live and read it aloud.", "Show a bad reply ('You are lying, we delivered on time') and ask learners what damage it does.", "Do a personal footprint search on yourself (prepared in advance) and show what you cleaned up: old public posts, a phone number in a bio, an unprofessional username."], "title": "Demonstration - footprint audit and review reply"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["Part A (10 min, individual): learners search their own name and usernames. They list what they find, mark anything they would not want an employer or customer to see, and check privacy settings. Remind them not to share private findings with the group unless they want to.", "Part B (15 min, individual): learners audit one business profile (their own business, a family business, or a business they will use as their campaign brief, with the owner's agreement) using the presence checklist, then write the improved version of the bio, the profile photo or logo choice, contact line and pinned post or highlight.", "Give a bio formula: what you sell + who it is for + where + how to order. Example: 'Fresh cakes and bread for birthdays and offices in Ruiru and Juja. Order on WhatsApp 07XX XXX XXX. Pay via M-Pesa Till.'", "Circulate. Check that learners use a business number and do not publish home addresses."], "title": "Presence audit and profile improvement"}, {"steps": ["Explain brief options: (a) a real local business with the owner's permission (a salon, cyber cafe, kinyozi, poultry farmer, fashion seller, food vendor); (b) a youth enterprise or community organisation (a youth recycling group, a church project, a sports club); (c) the learner's own business idea. The brief must be real enough to test with real people.", "Each learner writes a one-paragraph brief: business name, what it sells or does, location, current customers, the problem (for example few new customers, quiet weekdays, low trust online), and one thing the owner wants in the next month.", "In groups of three, learners take turns presenting their brief and drawing a channel map: list the channels, mark which ones the customers actually use, and choose two main channels and one support channel. Peers challenge choices ('Do your customers really use LinkedIn?').", "Learners save the brief and channel map in their DIRA LEARN portfolio folder. Remind them to tell the business owner what they are doing and get agreement before posting anything for the business."], "title": "Choose your campaign brief and draw a channel map"}, {"steps": ["Run the five assessment questions as a quick quiz (DIRA LEARN, a poll or on paper).", "Go through answers and correct misunderstandings immediately."], "title": "Knowledge check"}, {"steps": ["Ask three learners to say one thing they will change in their profile or business presence this week.", "Set the homework and remind learners to bring their brief to session 4."], "title": "Wrap-up and homework"}], "facilitator": {"delivery": ["Keep theory short and practical; every concept should be tied to a Kenyan business learners recognise.", "When learners choose briefs, push for real and specific businesses; a vague brief makes every later session harder.", "The footprint audit is personal; do not ask learners to show results publicly."], "preparation": ["Prepare the Shiru's Bakes example campaign slide and the presence checklist.", "Prepare screenshots of a business presence (fictional or with written consent) for the demonstration.", "Prepare a list of possible local briefs for learners who do not have a business to work with (for example a community group DIRA works with, with their consent)."], "after_session": ["Review the briefs in the portfolio folder and flag any that are too vague or unsafe before session 4.", "Record attendance in DIRA LEARN and upload the slides and templates to the session resources."], "inclusion_and_safeguarding": ["Remind learners never to post content about a business, customer or person without consent.", "Learners must not share home addresses, children's images or personal numbers in their projects.", "If a footprint search reveals harassment or abusive content about a learner, follow up privately and use the DIRA LEARN safeguarding process if needed.", "Consent and privacy: before using an identifiable person (face, voice or name), a photograph of someone, or a real business's name, logo, prices, customer details or results, the learner gets permission from that person or owner - in writing (a WhatsApp message is enough) for anything shown outside the class. Never children. Learners who cannot or do not wish to publish publicly use the private or simulated option, which is assessed with the same rubric and never marked down."]}, "demonstrations": [{"steps": ["Search the business on Google, Maps, Facebook, Instagram and TikTok.", "Score each checklist item live and note the top three fixes."], "title": "Business presence audit with the checklist"}, {"steps": ["Read the review, identify the real problem, write Acknowledge, Correct, Engage, then compare with a bad reply."], "title": "Replying to a negative review with ACE"}], "assessment_guides": [{"guide": "Awareness (status, TikTok, shares), consideration (Instagram, reviews, Google profile), conversion (WhatsApp order, M-Pesa till), loyalty (thank-you message, offer, referral).", "question": "Name the four stages of the customer journey and one channel that helps at each."}, {"guide": "Owned - business controls it (WhatsApp Business, Instagram page). Earned - others give it (reviews, shares). Paid - you pay for reach (boosted post, ad).", "question": "What is the difference between owned, earned and paid channels? Give an example of each."}, {"guide": "Information others create about you or that is collected automatically (tags, reviews, location data, search results).", "question": "What is a passive digital footprint?"}, {"guide": "Should acknowledge and apologise or thank, without arguing or blaming the customer.", "question": "A customer posts an angry review. Write the first sentence of your reply."}, {"guide": "Privacy and safety for the owner, professionalism, separating personal and business messages, continuity if staff change.", "question": "Why should a business use a business phone number on its profiles?"}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"678ee8f1-9b59-4c93-8108-b71f8c62de1c","session_id":"f0b76394-6bbd-4eb6-83d8-40ce47578278","content":{"version": "V13.2", "segments": [{"steps": ["Welcome learners by name as they join. Start on time even if some are late; latecomers will catch up in the icebreaker.", "Show the programme map on one slide: Week 1 shared core (sessions 1 and 2), Weeks 2 to 4 specialist track (sessions 3 to 8), session 8 is the showcase. Say: everything you make in this programme goes into a portfolio you can show an employer, a client or a funder.", "Build the learning agreement with the group. Ask: what do you need from each other to learn well? Write their answers. Make sure these five appear: respect different views, one person speaks at a time, cameras or attention on, what is shared personally stays in the room, phones on silent unless used for an activity.", "Explain safeguarding in plain words. If anyone, inside or outside the programme, makes you feel unsafe, tell the facilitator or use the support option in DIRA LEARN. Share only the support contacts that programme management has formally confirmed for this cohort (from the facilitator briefing). If a Safeguarding Lead or Deputy has been formally appointed and confirmed, name them; if not, do not name anyone or suggest that someone holds the role - say that concerns go to the facilitator or the DIRA LEARN support option and are passed to programme management. Do not promise secrecy; say concerns are shared only with the people who need to act on them.", "Ask everyone to type or say 'I agree' to the learning agreement. Save it and post it in the cohort space after the session."], "title": "Welcome and learning agreement"}, {"steps": ["Model it first: 'I am Wanjiru from Nakuru, I sell second-hand shoes on weekends, and one strength I have is patience with difficult customers.'", "In breakout groups of four (or around the room), each learner gives their name, where they are from, two true facts and one strength. Give 60 seconds each.", "Group members name one more strength they heard in the story (for example, the shoe seller also shows planning and negotiation).", "Bring the group back. Ask three volunteers to share a strength someone else spotted in them. Point out that others often see strengths we overlook."], "title": "Icebreaker - two truths and a strength"}, {"steps": ["Explain three words. A skill is something you learned to do (typing, cooking, editing video). A strength is something you do well and that energises you (listening, organising, making people laugh). A value is something that matters to you and guides decisions (honesty, family, faith, independence, community).", "Values exercise (5 minutes). Show a list of 20 values. Learners choose five, then cut to two. Ask: when did one of these two values help you make a hard decision? Two volunteers share.", "Teach self-leadership: you cannot control everything that happens, but you can choose your response. Use the example of a learner whose phone data runs out before a session: blame and miss it, or plan ahead (buy a bundle early, download materials, tell the facilitator).", "Teach the confidence loop: prepare, act, reflect. Confidence comes after action, not before it. Each small action you reflect on makes the next one easier.", "Self-talk. Read two sentences: 'I always mess up presentations' and 'My last presentation was nervous, so this time I will practise twice.' Ask which one helps. Learners rewrite one unhelpful sentence they say to themselves.", "Explain growth mindset in one sentence - abilities grow with practice and feedback. Connect it to the programme - you are not expected to be good at digital marketing, AI, content or business yet; you are expected to practise."], "title": "Values, confidence and self-leadership mini-workshop"}, {"steps": ["Hand out or share the strengths map template: four boxes - Strengths, Interests, Values, Help I can offer others. Learners fill each box with at least two items and one real example (8 minutes).", "Explain personal branding. Your personal brand is what people say about you when you are not in the room. It is built from what you are good at, what you stand for and how you help others, shown consistently online and offline. It is not pretending or showing off.", "Give the formula: I am a [strength] person who cares about [value]. I help [who] to [what] by [how]. Example: 'I am an organised and patient person who cares about honesty. I help small shops in my estate to keep customers coming back by answering messages quickly and politely.'", "Learners write their own two-sentence statement (5 minutes). Circulate and help anyone stuck by asking what friends usually ask them for help with.", "Three volunteers read their statements. Give one specific compliment and one improvement each (for example, make the 'who' more specific).", "Tell learners they will improve this statement in session 2 (online profile) and use it in the session 8 showcase."], "title": "Strengths map and personal brand statement"}, {"steps": ["Demonstrate three phrases. Introducing: 'Good morning, I am Brian, I am new in the team and I will be supporting customer orders.' Asking for help: 'I have tried X and Y, could you show me how you would do Z?' Receiving feedback: 'Thank you, can you give me an example so I can improve it?'", "In pairs, learners take turns using each phrase in a work scenario (a first day at a supermarket, an internship at a county office, a client call for a small design job). Two minutes per person.", "Ask the group which phrase felt hardest and why. Note that asking for help after trying something shows initiative, not weakness."], "title": "Confidence at work - practice rounds"}, {"steps": ["Ask learners to name signs of stress they notice in themselves (poor sleep, irritability, scrolling for hours, headaches, avoiding people). Write them down without judgement.", "Teach four basics: sleep (a regular time helps more than long weekend sleep), movement (a 10-minute walk counts), food and water, and screen boundaries (no phone for the first 30 minutes after waking, mute busy groups).", "Teach one recovery tool: the 4-4-6 breath (breathe in for 4, hold for 4, out for 6, repeat three times). Practise it together once.", "Support routes: a trusted friend or family member, a mentor, the facilitator, DIRA staff through the support option, and professional help. Say clearly that if anyone feels unsafe or is thinking of harming themselves, they should tell someone immediately and contact the emergency services or a crisis line; the facilitator will share the programme's approved contacts.", "Each learner writes two wellbeing habits they will keep during the four weeks on their goal card."], "title": "Wellbeing and resilience"}, {"steps": ["Explain SMART - Specific, Measurable, Achievable, Relevant, Time-bound. Weak goal: 'learn marketing'. SMART goal: 'By the end of week 4 I will create and present a basic marketing campaign for my aunt's cereals shop and get feedback from two real customers.'", "Learners write their goal and their first step for this week on the goal card (5 minutes).", "Pair learners as accountability partners (from different tracks if possible). Partners read each other's goals and make one suggestion to make it more measurable.", "Partners agree how they will check in (for example a WhatsApp message every Sunday evening). Remind them to keep messages respectful and on topic, and that they can tell the facilitator if a partnership is not working."], "title": "SMART goal and accountability partner"}, {"steps": ["Learners complete the baseline self-assessment in DIRA LEARN or on paper (confidence 1 to 5 in communication, digital skills, teamwork and goal setting).", "Exit ticket - three sentences: one thing I learned about myself today, one thing I will do before session 2, one question I still have.", "Close: thank learners, remind them of the session 2 date and time from the timetable, and ask them to bring a phone or computer with access to their social media or LinkedIn account if they have one."], "title": "Reflection and exit ticket"}], "facilitator": {"delivery": ["Keep the energy high in the first 20 minutes; this session sets the tone for the whole programme.", "Use learners' names often. Praise effort and specifics, not just talent.", "Watch the time on the strengths map; learners who are stuck often need one question ('what do friends ask you for help with?')."], "preparation": ["Check the DIRA LEARN cohort list and attendance register before the session; mark attendance in DIRA LEARN within the session.", "Prepare the programme map slide, the values list, the strengths map and goal card templates.", "Before the session, get from programme management the support contacts formally confirmed for this cohort, and whether a Safeguarding Lead and Deputy have been formally appointed. Share only confirmed contacts and appointments. Never invent a contact or name someone who has not been formally appointed.", "Write your own strengths map and personal brand statement in advance so you can model them."], "after_session": ["Post the learning agreement in the cohort space.", "Check exit tickets and answer common questions at the start of session 2.", "Note any learner who seemed withdrawn or did not participate and check in privately."], "inclusion_and_safeguarding": ["Values and wellbeing discussions can bring up personal difficulties. Never force anyone to share; allow 'pass'.", "If a learner discloses harm or risk, do not investigate. Listen, reassure, explain who you must tell, and record and escalate it through the DIRA LEARN safeguarding process the same day (immediately if urgent).", "Learners with low data or older phones can complete templates on paper and photograph them later."]}, "demonstrations": [{"steps": ["Write your own strengths map live (keep it honest and simple).", "Turn it into a statement using the formula, thinking aloud about each choice.", "Show a weak version ('I am hardworking and passionate') next to the improved one, and explain why specific beats general."], "title": "Modelling a personal brand statement"}, {"steps": ["Act out a poor example first (mumbling an introduction, apologising for asking a question), then the confident version.", "Ask learners what changed (eye contact, clear name and role, specific question)."], "title": "Confidence phrases"}], "assessment_guides": [{"guide": "Look for strengths (not just skills) with a concrete example. Prompt with 'when did you do that?' if the example is vague.", "question": "Name three of your strengths and give a real example of one of them."}, {"guide": "Skill is learned ability; strength is what you do well and that energises you; value is what matters and guides decisions.", "question": "What is the difference between a skill, a strength and a value?"}, {"guide": "The statement should name a specific group of people and a specific way of helping. 'Everyone' or 'many things' needs narrowing.", "question": "Read your personal brand statement. Who do you help, and how?"}, {"guide": "There should be a number, a deliverable or a clear observable result and a date (end of week 4).", "question": "Is your four-week goal SMART? Which part is the measurable part?"}, {"guide": "Any of the facilitator, the DIRA LEARN support option, a confirmed support contact shared in the session (including a formally appointed Safeguarding Lead or Deputy, if one was named), a mentor, a trusted adult, or emergency services for immediate danger.", "question": "Where can you go for support during the programme if you are struggling or feel unsafe?"}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"6f5621b4-dad5-4c5d-8667-b887022a7a3e","session_id":"ae6f04a8-ca62-4c3d-a398-60e98fbac35d","content":{"version": "V13.2", "segments": [{"steps": ["Each learner states their brief and what is left to finish in one sentence.", "Remind learners of the final project contents (strategy one-pager, edited video, photo set, branded designs, credit and consent log, portfolio with case-study notes)."], "title": "Project check-in"}, {"steps": ["Quality over quantity: three to five best pieces beat twenty average ones. Show variety - at least one video, one photo set and one design.", "Context: for each piece, add a short case study - the brief (who and what), the idea, your process (what you did and tools), the result (views, saves, client feedback, event turnout), and what you learned. Results can be small; be honest.", "Platforms: a Google Drive folder with a clear index (easy and free), Behance (design), Instagram with highlights by category, or a simple free website. Use a professional username and add contact details. For programme submissions, use restricted sharing (named people only) or upload the files in DIRA LEARN; making a portfolio public is optional and only after the consent log is checked.", "Working with clients (for example a Nakuru cafe paying KES 3,000 for four short reels, half paid upfront by M-Pesa): agree the brief, deliverables, deadline, number of revisions and price in writing (WhatsApp is fine) before starting; agree a deposit for larger jobs; deliver files in the right format and size. Never pay someone for a 'job' - that is a scam.", "Show the 'Otieno Shoots' portfolio index and one case study."], "title": "What makes a strong portfolio"}, {"steps": ["Learners finish production - final edits, reshoots if needed, designs, captions.", "They build their portfolio (folder or platform) with three to five best pieces and write one full case study and short notes for the others.", "Checkpoint at 25 minutes: the facilitator checks each learner has a finished video and design.", "The facilitator circulates for one-to-one coaching on quality and on the credit and consent log."], "title": "Creative project production"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["In groups of three, each learner shows their portfolio for 3 minutes. Peers use the portfolio checklist: strong first piece, variety, case-study notes, quality (light, sound, design), consistency with brand, credits and consent recorded, contact details.", "Each peer gives two strengths and two improvements."], "title": "Peer testing"}, {"steps": ["Learners make at least one improvement from the feedback.", "They prepare the showcase: self-pitch introduction, the brief, show the project (play the video, show designs), explain one creative choice and one result, what they learned, what next."], "title": "Revise and prepare the showcase"}, {"steps": ["Explain the showcase format (3 minutes plus 2 minutes of questions) and share the rubric.", "Set the homework."], "title": "Showcase briefing and homework"}], "facilitator": {"delivery": ["Protect the production time; this is where projects get finished.", "Prioritise coaching learners who are behind."], "preparation": ["Prepare the example portfolio and case study, the portfolio checklist and the client brief template.", "Set the session 8 room plan from the track group size (up to 12 - one room; 13 to 24 - two rooms; 25 to 36 - three rooms, or two live rooms plus a recorded-questions room) and line up co-facilitators and peer panels."], "after_session": ["Check that every learner has a complete project; message those at risk.", "Record attendance.", "Before marking, check that every portfolio submission is a restricted-access link or a DIRA LEARN upload; ask learners to change any public or \"anyone with the link\" sharing first."], "inclusion_and_safeguarding": ["Check consent logs before any content featuring people goes into a public portfolio.", "Remind learners not to publish personal phone numbers; use a business number or email.", "Consent and privacy: before using an identifiable person (face, voice or name), a photograph of someone, or a real business's name, logo, prices, customer details or results, the learner gets permission from that person or owner - in writing (a WhatsApp message is enough) for anything shown outside the class. Never children. Learners who cannot or do not wish to publish publicly use the private or simulated option, which is assessed with the same rubric and never marked down.", "Shared devices and low data: learners without a suitable phone shoot and edit in pairs or threes and take turns as camera operator, presenter and editor; plan uploads and downloads for programme Wi-Fi. Never require a paid app, premium template or paid music."]}, "demonstrations": [{"steps": ["Show a complete example portfolio index and read one case study aloud."], "title": "Portfolio walkthrough"}], "assessment_guides": [{"guide": "All checklist items present; first piece strong; credits and consent recorded.", "question": "Portfolio checked with the portfolio checklist."}, {"guide": "Brief, deliverables, deadline, revisions, price and payment terms.", "question": "What should you agree in writing with a client before starting work?"}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"75e2d05c-ff26-4a89-bced-40f738d4376c","session_id":"9f499c8f-488f-4042-9513-80724e43c372","content":{"version": "V13.2", "segments": [{"steps": ["Answer two or three common questions from the session 1 exit tickets.", "Quick poll (hands, chat or DIRA LEARN): rate yourself 1 to 5 on finding files, writing emails, using AI tools, staying safe online. Note the lowest-scoring area and give it a little extra time today."], "title": "Recap and digital confidence pulse check"}, {"steps": ["Demonstrate a programme folder in Google Drive or on a phone: DIRA LEARN > Week 1, Week 2, Week 3, Week 4, Portfolio. Show a good file name: '2026-11 Wanjiru Kamau - goal card.pdf'. Bad: 'IMG_2034.jpg'.", "Passwords: use a long passphrase (three random words plus a number), a different password for email, and turn on two-step verification on email, WhatsApp and social media. Show where the WhatsApp two-step setting is (Settings > Account > Two-step verification).", "Professional conduct - five rules: (1) reply within one working day, even if only to say when you will answer fully; (2) greet and sign off; (3) one clear request per message; (4) no voice notes for work requests unless the other person prefers them; (5) be on time for calls and test your audio and camera first.", "Workplace readiness: punctuality, keeping promises, telling your supervisor early when you will miss a deadline, dressing appropriately for video calls and for the workplace, respecting confidentiality. Ask: which of these have you seen go wrong at a job or a group project?"], "title": "Digital foundations and professional conduct"}, {"steps": ["Explain simply: AI assistants (such as ChatGPT, Gemini, Copilot, Claude or Meta AI in WhatsApp) predict useful text from patterns in huge amounts of data. They can draft, summarise, explain and brainstorm. They do not 'know' facts the way a reference book does, and can be confidently wrong.", "Live demo: ask an AI tool 'Write a short introduction message for a young person applying for an internship at a county government office.' Show the result. Then improve the prompt with role, task, context and format: 'You are a careers adviser. Write a 60-word WhatsApp message for Kevin, 21, from Machakos, who has a certificate in ICT and wants an internship at the Machakos County ICT office. Friendly and professional tone.' Compare.", "Show a limitation: ask the tool for a fact that changes (for example the current minimum wage or an application deadline) and explain that answers must be checked against an official source.", "Privacy rule: never paste ID numbers, M-Pesa PINs, passwords, other people's private messages or personal health details into an AI tool.", "Learners try one prompt for their own introduction message and improve it twice. They mark what they changed themselves (facts, tone, details AI got wrong). Learners without a device pair with someone who has one.", "Disclosure rule for DIRA LEARN work - if AI helped, say how in one line (for example 'First draft by AI, edited and fact-checked by me')."], "title": "AI awareness and prompt practice"}, {"steps": ["Teach the PAR structure - Purpose (why I am writing), Audience (who will read it), Request (what I want them to do). Show a poor message: 'Hi, am interested in the job pls reply.' Show a good one with greeting, who you are, which job, why you fit in one line, clear request, thanks and name.", "Learners write an email to a fictional employer (Subject: Application - Sales Assistant, Nyeri branch) with greeting, two-sentence introduction, request for an interview, sign-off and phone number. 5 minutes.", "Pair activity - listening: one partner explains their four-week goal for 60 seconds, the other summarises it in one sentence starting 'So what you want to achieve is...'. Swap.", "Ask two pairs to share. Highlight that summarising shows respect and avoids misunderstandings at work."], "title": "Clear communication practice"}, {"steps": ["Show two LinkedIn or Instagram profiles of fictional young Kenyans side by side. One: blurry photo, headline 'student', no bio, party photos public. Two: clear photo, headline 'Content creator | Helping Kisii small businesses get seen online', short bio, contact, examples of work.", "Learners improve one profile they already have (or draft one on paper): profile photo, headline (role or aim plus who you help), bio from their personal brand statement, contact method, one thing to hide or delete. Check privacy settings so personal phone numbers and home locations are not public. 8 minutes.", "Teach the 30-second self-pitch - Who I am, my strength, proof (one example), my ask. Example: 'I am Achieng from Homa Bay. I am good at explaining things simply - I tutor three Form Two students in maths. I am joining the Digital Marketing track and I am looking for a small business I can practise with.'", "In pairs, each learner delivers the pitch twice; the partner gives one 'keep' and one 'improve'. Remind them this pitch will grow into their session 8 showcase introduction."], "title": "Professional online presence and self-pitch"}, {"steps": ["Groups of four get one scenario each: (1) a WhatsApp job offer asking for a KES 1,500 'registration fee'; (2) an SMS saying 'I have sent you M-Pesa by mistake, please send it back' with no matching M-Pesa message from the official sender; (3) a stranger on Instagram asking for private photos and then threatening to share them; (4) a link to 'claim your free data bundle'.", "Each group answers: what are the warning signs, what should you do now, who can you tell, how can you report it. 6 minutes.", "Groups report back. Key teaching points: real employers do not charge application fees; check your actual M-Pesa balance and messages rather than reacting to an SMS; never send money or codes under pressure; for threats or image-based abuse do not pay, keep evidence (screenshots), block and report on the platform, tell a trusted person and the facilitator; image-based abuse and threats are crimes that can be reported to the police.", "Remind learners that the facilitator, the DIRA LEARN support option and the confirmed support contacts shared in session 1 are available if something like this happens during the programme."], "title": "Online safety scenarios"}, {"steps": ["Learners complete the 8-question core knowledge check (see assessment).", "Present the four tracks in one minute each - Digital Marketing (reach and win customers online and run a campaign), AI Tools (use AI responsibly to work faster and better), Content Creation (photos, videos and design that tell stories), Entrepreneurship & Business (turn an idea into a tested business concept and pitch).", "Learners confirm their track in DIRA LEARN with one sentence on how it connects to their four-week goal. Remind them the track choice follows the programme's rules in DIRA LEARN; anyone unsure should speak to the facilitator before the deadline."], "title": "Core module check and track confirmation"}, {"steps": ["Learners tick the digital safety checklist: two-step verification on email and WhatsApp, strong unique email password, privacy settings checked, programme folder created, profile improved.", "Reflection round: each learner says one word for how they feel about starting their track, and one action for this week.", "Explain what happens in week 2 (first track session) and what to bring (a charged phone, data or Wi-Fi, their programme folder).", "Thank learners for completing the core. Remind them that attendance at both core sessions is required before track learning, following the programme's attendance rules in DIRA LEARN."], "title": "Reflection, digital safety checklist and next steps"}], "facilitator": {"delivery": ["This session is full; keep segments to time and use a visible timer.", "In the AI demo, model checking and disclosure every time; learners copy what you do, not what you say.", "Profiles - learners should only change their own accounts. Do not ask anyone to log in on a shared device."], "preparation": ["Test the AI tool, screen sharing and the internet connection before the session. Prepare a backup screenshot of the AI demo in case the connection fails.", "Prepare the fictional before-and-after profiles (never use a real learner's profile without permission).", "Print or share the scenario cards, the digital safety checklist and the core knowledge check.", "Check the track selection rules and deadline in DIRA LEARN so you can answer questions accurately."], "after_session": ["Record attendance and core completion in DIRA LEARN.", "Check that every learner has confirmed a track; follow up with those who have not.", "Share the slides, checklist and templates in the session resources."], "inclusion_and_safeguarding": ["Online safety scenarios may be close to learners' real experiences. Offer a private conversation after the session and follow the DIRA LEARN safeguarding process if a learner discloses abuse or exploitation.", "Learners without smartphones work in pairs or on paper; never shame anyone for their device or data.", "Remind learners to keep personal phone numbers and home locations off public profiles.", "Consent and privacy: before using an identifiable person (face, voice or name), a photograph of someone, or a real business's name, logo, prices, customer details or results, the learner gets permission from that person or owner - in writing (a WhatsApp message is enough) for anything shown outside the class. Never children. Learners who cannot or do not wish to publish publicly use the private or simulated option, which is assessed with the same rubric and never marked down."]}, "demonstrations": [{"steps": ["Create the folder structure live in Google Drive or on a phone's file manager.", "Rename a badly named file to the standard format.", "Open WhatsApp settings and show where two-step verification is (do not enter a real PIN on screen)."], "title": "Organising a programme folder and turning on two-step verification"}, {"steps": ["Type a weak prompt and show the generic output.", "Add role, task, context and format; show the improved output.", "Find one error or invented detail and correct it, explaining why human checking matters."], "title": "Prompt improvement live"}, {"steps": ["Show a fictional weak profile and talk through what an employer would think.", "Edit the same profile into a strong one, reading the new headline and bio aloud."], "title": "Profile before and after"}], "assessment_guides": [{"guide": "Helps with drafting, summarising, explaining, brainstorming, translating. Limits include wrong or invented facts, out-of-date information, bias, no understanding of your situation.", "question": "Name three things an AI assistant can help with and two of its limitations."}, {"guide": "Passwords and PINs, ID or passport numbers, other people's private messages or data, health or financial details, confidential work information.", "question": "List three pieces of information you must never paste into an AI tool."}, {"guide": "Purpose, Audience, Request.", "question": "What does PAR stand for in a professional message?"}, {"guide": "Do not pay. Real employers do not charge fees. Verify the company through official channels, report and block, tell the facilitator.", "question": "A WhatsApp job offer asks you to pay KES 1,500 before the interview. What do you do?"}, {"guide": "It protects the account if someone gets your password or SIM; the attacker also needs the PIN or second step.", "question": "Why should you turn on two-step verification on WhatsApp and email?"}, {"guide": "Observe all four parts and a clear ask. Use the pitch rubric (clarity, confidence, specific proof).", "question": "Deliver your 30-second self-pitch. Did it include who, strength, proof and ask?"}, {"guide": "Expect a concrete change such as photo, headline, bio or privacy setting.", "question": "What would an employer think of your online profile? Name one change you made."}, {"guide": "The link should be explicit (for example 'Business track because my goal is to test my juice business idea').", "question": "Which track did you confirm and how does it connect to your goal?"}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"7a8df01e-2c5e-42c5-8fc6-214d71545ae5","session_id":"4d7fd967-9a3c-4e31-8fb2-e3a4af90cfcf","content":{"version": "V13.2", "segments": [{"steps": ["Show the journey: S3 strategy, storytelling and formats, S4 photography, lighting, composition, mobile video and sound capture, S5 video editing, audio and captions, S6 design, branding, visual storytelling and copyright, S7 portfolio and project build, S8 showcase.", "Show an example portfolio (fictional creator 'Otieno Shoots', a Kisumu creator making short videos for local food spots). Say that by session 8 each learner will have their own.", "Ask learners to name a Kenyan creator they follow and why they keep watching."], "title": "Welcome to Content Creation and track overview"}, {"steps": ["Purpose: why are you creating - to build a personal creator brand, to promote a business, to educate a community, or to tell stories for a cause? Purpose decides everything else.", "Audience: who exactly? 'Students in Eldoret who want to eat well on a budget' is stronger than 'young people'.", "Niche: what you want to be known for. A niche can be a topic (budget food), a style (funny skits in Sheng), or a place (Kisumu). Broad creators struggle to grow; focused creators get remembered.", "Goals: followers are not the only goal. Others include enquiries for a business, sign-ups for an event, saves and shares (people found it useful), or paid briefs.", "Pillars and rhythm: three or four pillars (for example 'cheap eats reviews', 'cook with me', 'campus food news'). A rhythm you can keep for three months (for example three short videos a week) beats a burst followed by silence.", "Creator content versus brand content: creators speak as themselves; brand content speaks for a business and follows its brand. Many creators earn by making brand content for clients - the portfolio will show both."], "title": "Content strategy and planning"}, {"steps": ["The hook: the first 2 seconds decide whether people keep watching. Hooks - a surprising visual, a question ('Can you eat lunch for KES 100 in town?'), a bold statement, a result first ('This KES 500 room makeover...').", "Story arc: setup (who and where), tension (a problem, a question or a challenge), payoff (the answer, the result, the emotion), call to action (follow, comment, visit).", "Character, conflict and change: people connect with people. A mama mboga starting her day at 4 am at Marikiti market and selling out by noon is a story; 'we sell vegetables' is not.", "Show, don't tell: instead of saying 'our tailor is skilled', show hands cutting fabric, a fitting and the client's smile.", "Authenticity and language: speak like your audience - English, Kiswahili, Sheng or your local language - as long as your target audience understands. Add captions so more people can follow.", "Play or describe two short examples and ask learners to identify the hook, tension and payoff."], "title": "Storytelling"}, {"steps": ["Short vertical video (TikTok, Instagram Reels, YouTube Shorts, Facebook Reels): 9:16 (1080 x 1920), usually 7 to 60 seconds for discovery content, strong hook, captions, trending or original audio.", "Feed photos and carousels (Instagram, Facebook, LinkedIn): 1:1 (1080 x 1080) or 4:5 (1080 x 1350); carousels tell step-by-step or before-and-after stories.", "Stories and WhatsApp status: vertical, short-lived, informal - good for behind the scenes and daily updates.", "Long-form video (YouTube): 16:9 (1920 x 1080), for tutorials, vlogs and interviews; thumbnail and title matter.", "Audio and podcasts: interviews and conversations; good sound is essential.", "Text-led platforms (LinkedIn, X): opinions, lessons and professional updates, often with an image or video.", "Platform specifications and limits change; check each platform's current help pages before publishing."], "title": "Content formats for different platforms"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["Take an idea: 'A day with a boda boda rider who delivers lunch in Thika'. Write the hook, tension and payoff.", "Draw a six-frame storyboard: frame number, shot type (wide, medium, close-up), what we see, what we hear (voice, sound, music), on-screen text, duration. Total 30 to 45 seconds.", "Show how the storyboard becomes a shot list for filming in session 4."], "title": "Demonstration - from idea to storyboard"}, {"steps": ["Learners choose the creative project brief: (a) a local business (with the owner's agreement), (b) a cause or community group, or (c) their own creator brand.", "Learners complete the strategy one-pager - purpose, audience, niche, goals, three or four pillars, main platforms, posting rhythm.", "Learners storyboard one 30 to 60-second piece for the brief (six to eight frames) with a clear hook and payoff.", "Learners without a device can draw the storyboard on paper and photograph it later."], "title": "Strategy one-pager, brief and storyboard"}, {"steps": ["In groups of three, each learner pitches the storyboard in 30 seconds. Peers say whether the hook would stop them scrolling and suggest one improvement.", "Ask two or three assessment questions aloud."], "title": "Peer pitch and knowledge check"}, {"steps": ["Remind learners to bring a charged phone with free storage to session 4 (shooting session).", "Set the homework."], "title": "Wrap-up and homework"}], "facilitator": {"delivery": ["Keep learners creating; theory segments should feel like inspiration, not lectures.", "Push for specific audiences and niches."], "preparation": ["Prepare two short example videos (public or your own) that show clear hooks and payoffs.", "Prepare the strategy one-pager and storyboard templates."], "after_session": ["Review storyboards and give one improvement each in DIRA LEARN.", "Record attendance."], "inclusion_and_safeguarding": ["Learners working with a business or group must get the owner's or leader's agreement.", "Content involving children needs a parent's or guardian's consent; discourage filming minors at all for this project.", "Consent and privacy: before using an identifiable person (face, voice or name), a photograph of someone, or a real business's name, logo, prices, customer details or results, the learner gets permission from that person or owner - in writing (a WhatsApp message is enough) for anything shown outside the class. Never children. Learners who cannot or do not wish to publish publicly use the private or simulated option, which is assessed with the same rubric and never marked down.", "Shared devices and low data: learners without a suitable phone shoot and edit in pairs or threes and take turns as camera operator, presenter and editor; plan uploads and downloads for programme Wi-Fi. Never require a paid app, premium template or paid music."]}, "demonstrations": [{"steps": ["Turn an idea into a hook, tension and payoff, then draw a six-frame storyboard with shot types, audio and text."], "title": "Idea to storyboard"}], "assessment_guides": [{"guide": "Creator content speaks as the creator; brand content speaks for a business and follows its brand.", "question": "What is the difference between creator content and brand content?"}, {"guide": "Grabs attention within 2 seconds - a question, bold claim, surprising visual or result first.", "question": "Write a hook for a video about cheap lunch spots in your town."}, {"guide": "Use visuals and actions to communicate instead of stating claims.", "question": "What does 'show, don't tell' mean?"}, {"guide": "9:16, 1080 x 1920.", "question": "What is the aspect ratio and size for a TikTok or Reel?"}, {"guide": "Specific niche and pillars linked to the audience.", "question": "Name your niche and two content pillars."}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"a0b85875-89eb-40ca-8aef-f7cf05644f84","session_id":"3eddf42c-25c2-44f3-8bba-2f8035458587","content":{"version": "V13.2", "segments": [{"steps": ["Ask three learners to read a caption from a Kenyan business that worked on them and say why.", "Note common patterns (a question, a problem they recognise, a clear price, urgency)."], "title": "Recap and caption hunt"}, {"steps": ["Hooks: the first line must stop the scroll. Types - a question ('Late cake again?'), a bold promise ('Birthday cakes delivered on time, every time'), a number ('3 ways to save on your child's party'), a story start ('At 6 am on Saturday...').", "Features versus benefits. Feature - 'eggless sponge'. Benefit - 'everyone at the party can enjoy it, even guests who don't eat eggs'. Practise turning two features into benefits together.", "AIDA: Attention (hook), Interest (relevant detail), Desire (benefit, proof), Action (call to action). Write one AIDA caption live for Shiru's Bakes.", "PAS: Problem ('Your office tea break needs snacks but the shop is far'), Agitate ('so people leave work and come back late'), Solution ('Shiru's delivers fresh bread and mandazi to your office every morning - order by 8 pm').", "Calls to action must be one clear step: 'WhatsApp us on 07XX', 'Tap the link to order', 'Save this post for your next party'.", "Tone: match the persona. Many Kenyan brands mix English with Kiswahili or Sheng, but it must sound natural to the audience. Honesty: do not claim 'best in Kenya' without proof, do not invent reviews, do not hide prices or conditions, and label paid partnerships."], "title": "Copywriting and persuasive messaging"}, {"steps": ["Learners write three captions for posts from their calendar - one AIDA, one PAS and one short caption for a status or story.", "Each caption must include a hook, a benefit, proof or detail, and one call to action.", "Partners swap captions and underline the hook and CTA. If they cannot find them, the writer rewrites."], "title": "Write your campaign captions"}, {"steps": ["Explain conversion: the moment someone takes the action you want (a message, an order, a booking, a sign-up). Engagement without conversion does not pay the rent.", "Speed: reply to enquiries quickly during business hours; many customers buy from whoever answers first. Use quick replies from session 4.", "The enquiry-to-order flow: greet, answer the question with the price, ask one question to understand the need, recommend, confirm details (size, date, location), give payment details (M-Pesa till or paybill, never a personal number for a registered business), confirm the order in writing, thank and follow up after delivery.", "Social proof: share reviews and customer photos with their consent, numbers ('120 cakes delivered this month'), before-and-after.", "Offers and urgency: a genuine limited offer can help ('10% off orders before Friday'), but fake countdowns and pressure damage trust.", "Reduce friction: prices in posts or a catalogue (customers who have to ask 'how much?' often leave), delivery areas and costs, clear payment steps.", "Retention: a thank-you message, asking for a review, and a reason to come back (a loyalty stamp on WhatsApp, a birthday message with permission)."], "title": "Customer engagement and conversion"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["In pairs, one learner is the customer (using a scenario card - for example 'asks the price, says it is expensive, wants delivery tomorrow in Juja'), the other replies as the business using the enquiry-to-order flow. Swap after 4 minutes.", "Debrief - which reply moved the conversation forward? How did you handle 'it is expensive' (explain value, offer a smaller option, never insult the customer)?"], "title": "Role-play - from enquiry to order"}, {"steps": ["Explain search in three steps: search engines crawl the web, index (store) pages, then rank results by relevance to the search, quality and trust, and for local searches, distance and prominence.", "Keywords and intent: the words people actually type. 'cake shop Ruiru', 'birthday cake delivery Juja', 'eggless cake near me'. Informational intent (how to) versus commercial intent (where to buy). Use Google autocomplete and 'People also ask' to find real phrases.", "Local SEO is the most useful part for small Kenyan businesses: a complete Google Business Profile shows on Google Maps and local results. Demonstrate the parts - business name (real name, no keyword stuffing), category, service area or address, hours, phone, website or social link, photos, products or services, posts, and reviews and replies.", "Reviews: ask happy customers for Google reviews with a short link; never buy fake reviews or offer payment for positive ones.", "On-page basics if the business has a website or blog: a clear page title and description with the main keyword, a heading that says what and where, fast pages, mobile-friendly, contact details on every page.", "Consistency: the same business name, phone and location on Google, Facebook, Instagram and directories helps search engines and customers trust the business."], "title": "Search engine optimisation fundamentals and Google Business Profile"}, {"steps": ["Learners use Google autocomplete to list ten search phrases real customers might use, marking the five most relevant.", "Learners draft the Google Business Profile using the template - name, category, area, hours, a 250-word description using keywords naturally, five product or service entries and three photo ideas.", "If the owner agrees and the business does not have a profile, the owner can create or verify it later; learners must not create profiles for businesses without the owner's permission."], "title": "Keyword list and Google Business Profile draft"}, {"steps": ["Run the assessment questions; discuss two answers in depth."], "title": "Knowledge check"}, {"steps": ["Remind learners that session 7 is the campaign build and they must bring all parts (brief, persona, platform plan, brand kit, calendar, graphics, captions).", "Set the homework."], "title": "Wrap-up and homework"}], "facilitator": {"delivery": ["Keep copywriting practical; learners should write more than they listen.", "Stress honesty and consent - persuasive does not mean misleading."], "preparation": ["Prepare scenario cards for the role-play and a fictional Google Business Profile walkthrough.", "Collect examples of good and weak captions from public Kenyan business pages."], "after_session": ["Check every learner has the parts needed for the session 7 build; message those missing pieces.", "Record attendance."], "inclusion_and_safeguarding": ["Learners must not create or edit profiles for businesses without the owner's permission.", "Testimonials and customer photos need the customer's consent."]}, "demonstrations": [{"steps": ["Start from a feature list, find the benefit, write hook, interest, desire and CTA, then cut unnecessary words."], "title": "Writing an AIDA caption live"}, {"steps": ["Show each field of a fictional or consenting business profile and how reviews and replies appear on Maps."], "title": "Google Business Profile walkthrough"}], "assessment_guides": [{"guide": "Attention, Interest, Desire, Action.", "question": "What does AIDA stand for?"}, {"guide": "For example 'last-minute party? You still get a fresh cake on time'.", "question": "Turn the feature 'delivery within 2 hours' into a benefit."}, {"guide": "Reply quickly with the price or a clear range and the next step; ideally prices are already in the post or catalogue.", "question": "A customer asks 'how much?' in a comment. What should you do?"}, {"guide": "Correct category, complete details (area, hours, phone), photos, products or services, reviews and replies, posts.", "question": "Name three parts of a Google Business Profile that help a business get found."}, {"guide": "It misleads customers, breaks platform rules and can lead to removal; trust is lost if discovered.", "question": "Why should you never buy fake reviews?"}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"a5be3832-2b53-4cf9-bdff-4a5726f75abc","session_id":"8a5cdcac-0981-4a47-9e37-f929a17941e5","content":{"version": "V13.2", "segments": [{"steps": ["Learners confirm they have their clips and a free editor installed. Pair anyone without footage with a partner's clips or the facilitator's sample footage.", "Show a before (raw clips) and after (finished 40-second video) to show what they will make today."], "title": "Recap and footage check"}, {"steps": ["Principles: (1) hook first - start with the most interesting moment, not 'Hi guys'; (2) cut dead time - remove pauses, setup and repeated shots; (3) cut on action - cut when something moves so the edit feels natural; (4) pacing - change shot every 2 to 4 seconds for short-form; (5) sequences - wide, medium, close-up; (6) transitions - simple cuts are best, flashy effects distract.", "Live edit in a free mobile editor (for example CapCut, InShot or VN): import clips, put them in storyboard order, trim the start and end of each clip, split and delete a mistake, move the best shot to the start, adjust speed of one B-roll shot, add a title text, adjust brightness and contrast slightly.", "Safe zones: keep text and faces away from the bottom and right edges where platform buttons and captions cover the screen."], "title": "Editing principles and demonstration"}, {"steps": ["Learners edit their storyboard footage into a 30 to 60-second video, following the principles and their storyboard (they may improve the story while editing).", "Checkpoint at 15 minutes: the hook is in the first 2 seconds and there is no dead time.", "The facilitator circulates and helps with the app."], "title": "Edit your video"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["Levels: voice must be clearly louder than music; lower the music under speech (many editors call this ducking or allow manual volume).", "Noise reduction: use the editor's noise reduction feature if available; it cannot fix very bad recordings, so capture well.", "Voice-over: record in a quiet room close to the phone, speak slowly and clearly, re-record mistakes.", "Music licensing: songs belong to their creators and labels. Platforms such as TikTok and Instagram provide music libraries that are licensed for use on that platform within their terms; business accounts may have fewer choices. Royalty-free libraries (for example the YouTube Audio Library) provide music you can use under their terms. Using a popular Kenyan or international song from elsewhere without a licence can get your video muted or removed, or lead to a copyright claim.", "Learners add music or a voice-over to their video and balance the levels."], "title": "Audio and sound - editing and legal music"}, {"steps": ["On-screen captions: many people watch without sound, and captions make content accessible to people who are deaf or hard of hearing. Use the editor's auto-captions, then correct every error - names, places, Kiswahili and Sheng words are often wrong. Keep two lines maximum, high contrast, inside the safe zone.", "Post caption structure: hook (first line visible before 'more'), value or story (what the viewer gets, or the story behind the video), call to action (follow, comment, share, visit), and a few relevant hashtags or keywords that people actually search.", "Creative writing techniques: specific details ('the smell of mandazi at 6 am in Kariokor'), a question to start conversation, humour that fits the audience, and short sentences.", "Learners add on-screen captions and write the post caption."], "title": "Captions and creative writing"}, {"steps": ["Final check: hook, no dead time, sound levels, captions correct, text in safe zones, ending with a call to action or logo.", "Export: 1080p, 30 fps for most platforms; 9:16 for short vertical video; save a copy to the cloud. Remove the editor's watermark only if the app's terms allow it.", "Learners save the final video in their DIRA LEARN portfolio folder."], "title": "Finish and export"}, {"steps": ["Screen three or four videos (volunteers). The group gives feedback on the hook, pacing, sound and captions.", "Ask two or three assessment questions."], "title": "Screening and knowledge check"}, {"steps": ["Set the homework and remind learners to bring their brand ideas to session 6."], "title": "Wrap-up and homework"}], "facilitator": {"delivery": ["Learners progress at different speeds; pair confident editors with beginners.", "Do not try to teach every feature; teach the 20% that gives 80% of the result."], "preparation": ["Install and test the editor yourself; prepare sample footage for learners who have none.", "Prepare a before-and-after example video."], "after_session": ["Review the videos in the portfolio folder and give one improvement each.", "Record attendance."], "inclusion_and_safeguarding": ["Phones with little storage struggle; let learners edit a shorter video or use a partner's phone.", "Remind learners that content must respect the consent given by the people filmed.", "Consent and privacy: before using an identifiable person (face, voice or name), a photograph of someone, or a real business's name, logo, prices, customer details or results, the learner gets permission from that person or owner - in writing (a WhatsApp message is enough) for anything shown outside the class. Never children. Learners who cannot or do not wish to publish publicly use the private or simulated option, which is assessed with the same rubric and never marked down.", "Shared devices and low data: learners without a suitable phone shoot and edit in pairs or threes and take turns as camera operator, presenter and editor; plan uploads and downloads for programme Wi-Fi. Never require a paid app, premium template or paid music."]}, "demonstrations": [{"steps": ["Import, order, trim, split, reorder for the hook, speed change, title, brightness, export."], "title": "Live mobile edit"}, {"steps": ["Add music, lower it under the voice, generate auto-captions and correct errors."], "title": "Audio balance and captions"}], "assessment_guides": [{"guide": "Viewers decide in the first 2 seconds whether to keep watching.", "question": "Why should the best moment come first in a short video?"}, {"guide": "Cutting during a movement so the transition feels natural.", "question": "What does 'cut on action' mean?"}, {"guide": "Silent viewing, accessibility for deaf and hard of hearing viewers, clarity.", "question": "Why add on-screen captions?"}, {"guide": "Platform music libraries within their terms, royalty-free libraries under their licences, music you have permission or a licence for, your own music.", "question": "Where can you get music you are allowed to use?"}, {"guide": "1080 x 1920 (9:16), 1080p, 30 fps.", "question": "What export settings are a safe default for short vertical video?"}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"b6f6ca64-acc5-4651-8fe6-541561ef82b6","session_id":"708f0f85-2909-443e-b47e-314a2934f2ea","content":{"version": "V13.2", "segments": [{"steps": ["Show the track journey: S3 understanding AI and responsible use, S4 prompting, research and fact-checking, S5 writing, images and presentations, S6 productivity, business, automation, privacy and bias, S7 project build and testing, S8 showcase.", "Show one example final project (for example a 'Customer reply kit' made with AI for a Kitengela hardware shop - prompts, checked answers, a test with the owner). Say that by session 8 each learner will demonstrate one like it.", "Quick poll: which AI tools have you used, and for what? Collect answers in the chat or on the board."], "title": "Welcome to AI Tools and track overview"}, {"steps": ["Define AI: computer systems that do tasks that usually need human intelligence - recognising images, understanding language, making predictions, generating text or pictures.", "Explain machine learning with an example: an M-Pesa-style fraud system learns from millions of past transactions what normal and suspicious patterns look like, then flags unusual ones. Nobody writes a rule for every case; the system learns patterns from examples.", "Explain generative AI and large language models: they were trained on enormous amounts of text and learned to predict the next word. When you ask a question, they produce a likely-sounding answer word by word. That is why they write fluently - and why they can invent facts, quotes, references and numbers that sound right but are false. This is called a hallucination.", "Everyday AI in Kenya: email spam filters, Google Maps traffic estimates, phone camera face detection, translation apps, bank and mobile money fraud alerts, customer-care chatbots on company websites and WhatsApp, social media feeds choosing what you see.", "Three key limits to remember: AI does not know your situation unless you tell it; its information may be out of date; it can repeat biases from its training data. AI is a powerful assistant, not an authority."], "title": "What AI is and how it works"}, {"steps": ["Walk through the tool families with one use each: chat assistants (draft, explain, brainstorm); image tools (create illustrations, edit photos); voice and transcription (turn a recorded meeting into notes); translation (English to Kiswahili, with checking); research tools that cite sources; AI inside apps (Canva's AI features, writing help in Google Docs or Microsoft tools, Meta AI in WhatsApp); coding and spreadsheet assistants (explain a formula).", "Free versus paid: many tools have free tiers with limits; some features need payment or a specific country; terms and availability change, so check the tool's current terms. Data use: free tools may use your inputs to improve their models unless you change settings.", "Ask learners to match five everyday tasks (writing a CV summary, transcribing a voice note, designing a poster, translating a notice, checking a fact) to a tool family."], "title": "Types and uses of AI tools"}, {"steps": ["Task 1, explain: 'Explain what a KRA PIN is and why a young person starting work needs one, in simple English, 100 words.' Read the answer and point out what you would confirm on the official KRA website.", "Task 2, draft: 'Draft a polite WhatsApp message to a client asking for payment of an overdue invoice of KES 4,500 for a logo design.' Show edits to tone and details.", "Task 3, summarise: paste a public, non-personal article or notice (for example a county youth-fund announcement) and ask for five bullet points. Compare with the original; find anything missed or wrong.", "Model the AI task log - task, tool, prompt, what was good, what I checked or changed, final decision."], "title": "Demonstration - three AI tasks and what needed checking"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["Learners choose three real tasks from their life or work - one explain, one draft, one summarise (for example explain a topic from their course, draft a message to a landlord or customer, summarise a public notice).", "For each, they fill the AI task log: tool, prompt, output quality (1 to 5), what they checked and how (source, own knowledge, asking someone), what they changed, and whether they would use the output.", "Remind learners of the privacy rule - no personal data, passwords, ID numbers, other people's private messages or confidential work information in prompts.", "Learners without a device pair up; one types, both evaluate."], "title": "Your three AI tasks"}, {"steps": ["Groups of four discuss one scenario each: (1) a college student submits an AI-written assignment as their own; (2) a job seeker asks AI to add experience they do not have to a CV; (3) someone makes an AI image of a classmate in an embarrassing situation; (4) a small business pastes customers' names and phone numbers into an AI tool to write personalised messages; (5) a youth group shares an AI-written health claim on WhatsApp without checking.", "Each group answers: what is the harm, who is affected, what would be the responsible choice? 8 minutes. Groups report back in one minute each.", "Draw out five principles: honesty and disclosure (say when AI helped); privacy (protect personal data - Kenya's Data Protection Act 2019 gives people rights over their personal data); accuracy (verify before sharing); fairness (watch for bias and stereotypes); human responsibility (you are accountable for what you submit, send or publish).", "Agree the group AI use code: six to eight short rules written by the group, including a disclosure line format ('AI-assisted: drafted with [tool], edited and checked by me'). Everyone agrees in the chat or by signing.", "Note that making or sharing sexual or humiliating fake images of a real person can cause serious harm, can be a crime and must be reported."], "title": "Responsible AI scenarios and group AI use code"}, {"steps": ["Run the assessment questions as a quick quiz and discuss the answers."], "title": "Knowledge check"}, {"steps": ["Each learner shares one surprising thing they learned about AI today.", "Set the homework and post the group AI use code in the cohort space."], "title": "Wrap-up and homework"}], "facilitator": {"delivery": ["Keep explanations concrete; avoid technical jargon unless a learner asks.", "Model checking every single time you show an AI output."], "preparation": ["Test the AI tools on the venue internet; prepare screenshots of the three demo tasks as a backup.", "Choose a public, non-personal text for the summarising demo.", "Print or share the task log template and scenario cards."], "after_session": ["Post the group AI use code in the cohort space and upload slides and templates.", "Review task logs and note common checking gaps to address in session 4.", "Record attendance."], "inclusion_and_safeguarding": ["Some scenarios (fake images) may relate to learners' experiences. Allow learners to pass, and follow the DIRA LEARN safeguarding process if anyone discloses image-based abuse.", "Do not require learners to create accounts that need personal data they are not comfortable sharing; use pairs or the facilitator's demo instead.", "Consent and privacy: before using an identifiable person (face, voice or name), a photograph of someone, or a real business's name, logo, prices, customer details or results, the learner gets permission from that person or owner - in writing (a WhatsApp message is enough) for anything shown outside the class. Never children. Learners who cannot or do not wish to publish publicly use the private or simulated option, which is assessed with the same rubric and never marked down.", "Shared devices and low data: pair or group learners on one device and rotate the typing role each task; learners without a device or data follow the shared screen and record their work on paper or later on programme Wi-Fi. Never require a paid tool or plan, or an account that needs personal data the learner does not want to give."]}, "demonstrations": [{"steps": ["Run explain, draft and summarise tasks live; for each, show the checking step and the task log entry."], "title": "Three AI tasks with checking"}], "assessment_guides": [{"guide": "It predicts likely next words based on patterns learned from huge amounts of text; it does not look facts up unless connected to search.", "question": "In simple words, how does a chat assistant produce an answer?"}, {"guide": "A confident but false or invented output (fake facts, references, quotes or numbers).", "question": "What is a hallucination?"}, {"guide": "Any three tool families with a sensible use.", "question": "Name three types of AI tools and one use for each."}, {"guide": "Passwords and PINs, ID numbers, other people's personal data, health information, confidential work data.", "question": "Give two examples of information you must never put into an AI tool."}, {"guide": "Names the tool and what the learner did (edited, checked).", "question": "Write your disclosure line for a piece of work AI helped with."}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"b9997670-31c6-4ec4-b1b9-fc0ba6ccd8e3","session_id":"33a50c50-93d0-4483-8653-2833315c0964","content":{"version": "V13.2", "segments": [{"steps": ["Welcome learners and any guests (business owners, DIRA staff, mentors, invited employers). Thank business owners who allowed learners to work with them.", "Explain the format: three minutes to present, two minutes of questions, then the next presenter. Share the rubric: clarity of objective and audience (20%), quality and consistency of content (25%), channel and budget choices (20%), measurement and results (20%), presentation and answers (15%).", "Etiquette: phones on silent, cameras on if online, respectful questions, applause after each presenter.", "Assign each learner to give written feedback on two specific presenters (so every presenter gets at least two pieces of peer feedback)."], "title": "Showcase set-up and expectations"}, {"steps": ["Run the campaigns with the session 8 room plan in the facilitator instructions: the first six presenters in each room go in this block, each with 3 minutes plus 2 minutes of questions.", "Learners present in the published order. Keep strict time with a visible timer; give a 30-second warning.", "Each presentation covers: self-pitch introduction; the brief; SMART objective; persona; channels; brand and three posts; budget; KPIs and results or test findings; what they learned and would do next.", "Ask at least one question per presenter, such as: 'Why did you choose this platform for this persona?', 'What would you change if you had KES 5,000 more?', 'What does your cost per result tell you?', 'How did you get consent for these photos?'", "Score each presenter on the rubric and note one strength and one improvement."], "title": "Campaign presentations and questions - block 1"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["The remaining presenters in each live room (7 to 12) go now, with the same timer, rubric and question approach as block 1.", "In a recorded-questions room, do not replay the recordings (the panel scored them before the session); give each recorded presenter 2 minutes of live questions about their campaign.", "Each room's panel hands its completed campaign rubric sheets to the room facilitator before the feedback round."], "title": "Campaign presentations and questions - block 2"}, {"steps": ["Learners give their written feedback to the two presenters they were assigned (in DIRA LEARN or on cards).", "Facilitator summarises patterns: what strong campaigns had in common (specific persona, consistent brand, clear CTA, honest measurement) and the most common improvements.", "Model receiving feedback - thank, ask for an example, decide what to act on."], "title": "Feedback round"}, {"steps": ["Show how to turn the campaign into a one-page case study: the challenge, what you did, results, what you learned, and visuals. Add it to LinkedIn (Featured section), a Google Drive portfolio folder or a simple online portfolio.", "Pitch formula for interviews and clients: who you are, what you can do, proof (this campaign and its numbers), what you are looking for. Example: 'I am Brian, a digital marketer from Thika. I recently ran a two-week WhatsApp and Facebook campaign for a bakery that brought 14 new orders for KES 1,200 in ads. I am looking for an internship or small businesses that need help with social media.'", "Pathways: internships and entry-level jobs (marketing assistant, social media assistant, customer service), freelance and online work (Kenya's Ajira Digital programme provides training and information on online work), and supporting or running a business. Warn again about job scams that ask for fees.", "Professional follow-up: within two days, thank the business owner, share the results summary and ask for a short testimonial or reference; connect with guests on LinkedIn with a personal note.", "Learners practise their pitch once in pairs."], "title": "Pitching yourself and workplace readiness"}, {"steps": ["Learners complete the 30-day action plan: one main goal, four weekly actions (for example week 1 finish the case study, week 2 offer services to three businesses, week 3 publish two portfolio posts, week 4 apply to two internships), one measure of success, one person who will hold them accountable and one risk with a plan.", "Learners share their main goal with their accountability partner from core session 1.", "Remind learners that the plan is part of their final project submission in DIRA LEARN."], "title": "30-day action plan"}, {"steps": ["Celebrate - a short recognition of every learner's campaign (for example one word of praise each).", "Explain next steps - submitting the final project, how results and certificates work in DIRA LEARN according to the programme's rules, and how to stay connected with DIRA."], "title": "Celebration and close"}], "facilitator": {"delivery": ["Be strict on time but warm; nervous presenters can use notes.", "Celebrate honest reporting of weak results - the learning is what matters.", "Session 8 room plan - Room plan (set in session 7 from the track group size; the session is never extended): up to 12 learners - one room; 13 to 24 - two rooms in parallel; 25 to 36 - three rooms, or two live rooms plus one recorded-questions room. Each live room takes at most 12 presenters: 6 in each 30-minute block, 3 minutes to present and 2 minutes of questions each.", "Every room has a facilitator or briefed co-facilitator (another trainer, a mentor or DIRA staff member who knows the rubric and the safeguarding expectations) and a peer panel of two learners who present in the other block. All rooms use the same rubric.", "Recorded option: learners in a recorded-questions room, and anyone who cannot present live (absence, connection problems, anxiety, or the privacy option), submit a 3-minute recording - video, or a voice note with slides for low data - by the day before session 8. The panel scores it in advance with the same rubric; in session 8 each recorded presenter answers 2 minutes of live questions (12 per block). If more learners need the recorded option than one room can take, the panel sends written questions and the learner answers them in DIRA LEARN.", "Timekeeping: a visible timer with a 30-second warning; stop at 3 minutes. If a block runs late, cut questions to 1 minute - do not extend the session."], "preparation": ["Publish the presentation order in advance and confirm each learner's materials work (screen sharing or slides).", "Invite business owners and guests at least a week before; brief guests on respectful questioning.", "Confirm the room plan: count the learners in the track group, book the rooms and co-facilitators, brief the peer panels, and publish each room's presenter order and the list of recorded presenters by the end of session 7."], "after_session": ["Enter rubric scores and feedback in DIRA LEARN grading for the final project.", "Share the case study template and collect business owners' feedback where offered.", "Record attendance."], "inclusion_and_safeguarding": ["Learners who cannot present live (connectivity, illness) can submit a recorded presentation according to the programme's rules.", "Guests must not contact learners privately without going through the programme; remind them of the safeguarding expectations."]}, "demonstrations": [{"steps": ["Before the session, prepare a 3-minute example presentation (Shiru's Bakes) and share it as a reference recording or slide set for learners who want an example. Do not use showcase time for it."], "title": "Model presentation"}], "assessment_guides": [{"guide": "Use the rubric descriptors. Results do not need to be large; honest measurement and good reasoning score well.", "question": "Presentation scored with the showcase rubric (objective and audience, content quality, channel and budget choices, measurement and results, presentation and answers)."}, {"guide": "Look for a change based on evidence from results or feedback.", "question": "What would you change in your campaign if you ran it again, and why?"}, {"guide": "Who, what, proof with a number, ask.", "question": "Deliver your pitch using the campaign as proof."}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"e525f2dc-825d-4a8d-83b9-6dd8eb0f1c2e","session_id":"413e6de4-6a34-47bc-b4c5-8d826bd7760e","content":{"version": "V13.2", "segments": [{"steps": ["Each learner shares their final project brief in one sentence. Note them for session 7.", "Introduce the human-first-and-last idea - you decide the purpose and facts first, and you edit and check last."], "title": "Recap and project brief check"}, {"steps": ["Workflow: (1) plan - write your purpose, audience and key points yourself; (2) prompt - give AI your points and ask for a draft; (3) edit - rewrite in your voice, cut generic phrases; (4) check - facts, names, numbers, tone; (5) disclose.", "Common uses: improve a cover letter, shorten a long message, change tone (formal for a bank, friendly for customers), turn notes into a report, fix grammar, translate.", "Your voice: AI writing often sounds generic ('In today's fast-paced world...'). Show how to remove filler and add personal detail and local examples.", "Truthfulness: AI must never add skills, experience, qualifications or achievements you do not have to a CV or application. Employers check, and false claims can cost the job.", "Translation: AI translation into Kiswahili is useful but can be unnatural or wrong; ask a fluent speaker to check important messages.", "Integrity: in college and at work, follow the rules on AI use; when allowed, disclose."], "title": "AI-assisted writing"}, {"steps": ["Learners choose a real piece: a cover letter paragraph, a message to a client, a post for a community group, or a section of their project.", "They follow the workflow, keeping the AI draft and their edited version side by side and highlighting what they changed.", "Partners read the final version and say whether it sounds like the writer."], "title": "Write with AI in your own voice"}, {"steps": ["Explain image prompts: subject (a young woman selling fresh fruit), setting (a busy market in Kisumu in the morning), style (realistic photo, or bright flat illustration), lighting (soft morning light), composition (close-up, eye level, space on the right for text).", "Demonstrate in an available free image tool (for example the image features in Canva, Copilot, Gemini or Meta AI, depending on what works in Kenya at the time). Show two variations and an edit.", "Show common problems: distorted hands, unreadable text, wrong local details (wrong currency, unrealistic markets), and stereotyped depictions of Africans or women. Discuss how to correct them with better prompts or by using real photos instead.", "Responsible rules: never create images of real people without their consent; never create fake images meant to deceive (fake events, fake products, fake evidence); label AI images ('AI-generated image'); for real products and businesses, prefer real photos because customers expect accuracy. Copyright rules for AI images are still developing in many countries, so do not claim exclusive ownership without checking the tool's terms."], "title": "AI images and creative work"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["Learners write an image prompt for their project (an illustration for a poster, a concept image for a presentation) using the five parts.", "They improve the prompt twice and keep the best result, noting problems they fixed.", "They label the image and write one sentence on why AI was (or was not) the right choice for it."], "title": "Create an AI-assisted image"}, {"steps": ["Demonstrate: prompt 'Act as a presentation coach. Create a five-slide outline for a 3-minute talk to a youth group in Machakos about using AI safely for job searching. One key idea per slide, with a title and three short points and speaker notes.' Review and edit the outline.", "Show how to build slides quickly in Google Slides, PowerPoint or Canva (some have AI design features), using big text, one idea per slide and real or labelled images.", "Learners create a five-slide presentation for their final project idea or a topic of their choice, with speaker notes.", "They check every fact and number on the slides and add a disclosure line on the last slide."], "title": "AI for presentations - demonstration and build"}, {"steps": ["Learners post their image and first slide in the cohort space; each learner comments on two others (one strength, one fix).", "Ask two assessment questions aloud."], "title": "Gallery review and knowledge check"}, {"steps": ["Remind learners to save all outputs in their project folder.", "Set the homework."], "title": "Wrap-up and homework"}], "facilitator": {"delivery": ["Time-box the image activity; image tools can absorb a whole session.", "Stress that learners' own judgement is what makes the output valuable."], "preparation": ["Check which free image tools currently work in Kenya on the venue internet; prepare backups.", "Prepare a generic AI paragraph for the 'remove the robot' exercise."], "after_session": ["Review the gallery and give feedback on disclosure and checking.", "Record attendance."], "inclusion_and_safeguarding": ["No images of real people (including classmates) without consent; no sexual, violent or humiliating content.", "If a learner creates harmful content, stop the activity, address it privately and follow the programme's conduct and safeguarding processes.", "Consent and privacy: before using an identifiable person (face, voice or name), a photograph of someone, or a real business's name, logo, prices, customer details or results, the learner gets permission from that person or owner - in writing (a WhatsApp message is enough) for anything shown outside the class. Never children. Learners who cannot or do not wish to publish publicly use the private or simulated option, which is assessed with the same rubric and never marked down.", "Shared devices and low data: pair or group learners on one device and rotate the typing role each task; learners without a device or data follow the shared screen and record their work on paper or later on programme Wi-Fi. Never require a paid tool or plan, or an account that needs personal data the learner does not want to give."]}, "demonstrations": [{"steps": ["Write your key points, prompt for a draft, then visibly edit it into your own voice and check facts."], "title": "Human-first-and-last writing"}, {"steps": ["Build an image prompt part by part, generate variations, fix a problem with a better prompt."], "title": "Image prompt anatomy and fixes"}, {"steps": ["Generate an outline, edit it, build two slides live and add speaker notes."], "title": "AI-assisted presentation"}], "assessment_guides": [{"guide": "Plan, prompt, edit, check, disclose.", "question": "What are the five steps of the human-first-and-last workflow?"}, {"guide": "It is dishonest, employers verify, it can cost the job and damage reputation.", "question": "Why must you never let AI add experience to your CV?"}, {"guide": "Subject, setting, style, lighting, composition.", "question": "Name the five parts of a good image prompt."}, {"guide": "When showing real products, people or places customers expect to be accurate.", "question": "When should a business use a real photo instead of an AI image?"}, {"guide": "A disclosure line and, where facts were used, sources.", "question": "What should the last slide of an AI-assisted presentation include?"}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"f401d801-8e12-4127-9c93-e8c315351c58","session_id":"9fb8a50c-010c-4757-b734-70dac518f759","content":{"version": "V13.2", "segments": [{"steps": ["Learners share customer reactions to their price. Discuss what they will change (price, offer, target customer).", "Introduce today - getting customers, keeping them and selling honestly."], "title": "Recap and price reactions"}, {"steps": ["Simple brand: a memorable name, a promise customers can rely on ('Fresh juice, made this morning'), and a consistent look (colours, logo, clean stall or packaging).", "Positioning: complete 'Customers choose us instead of [alternative] because [difference].'", "The 4Ps in plain words: Product (what exactly you sell), Price (from session 5), Place (where and how customers buy - stall, delivery, online), Promotion (how they hear about you).", "Low-cost marketing for Kenyan small businesses: word of mouth and referrals (offer a reward for bringing a friend), community presence (chamas, churches, mosques, estate groups - with permission), a WhatsApp Business catalogue and status, one main social platform, signage and samples. The Digital Marketing track covers these channels in depth; here learners choose what fits their business and budget.", "One-page marketing plan: target customer, key message, channels (two or three), offer for the first customers, budget, and measures (enquiries, sales, repeat customers)."], "title": "Branding and marketing a small business"}, {"steps": ["Learners complete the one-page marketing plan using their business model and finance numbers.", "Partners check that the marketing budget fits the finance template and that the channels match the target customer."], "title": "One-page marketing plan"}, {"steps": ["Customer journey: before (hearing about you, asking questions), during (ordering, paying, receiving), after (using the product, follow-up, complaints, coming back). Draw it for the juice business.", "Moments of truth: the points that decide whether customers return - the first reply on WhatsApp, the delivery time, the taste, how a complaint is handled.", "Service standards: simple promises you always keep, for example 'reply within 15 minutes during opening hours', 'deliver within an hour in town', 'greet every customer by name if known'.", "Complaints: Listen without interrupting, Apologise sincerely, Fix it (replace, refund or compensate fairly), Follow up. A well-handled complaint often creates a loyal customer.", "Repeat customers and referrals: a thank-you message, a loyalty card (paper or WhatsApp stamps), asking happy customers to tell a friend."], "title": "Customer service and customer experience"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["Learners map their customer journey (before, during, after), mark two moments of truth and write a service standard for each.", "In pairs, role-play a complaint (a late delivery, a wrong item, a rude staff member) using Listen, Apologise, Fix, Follow up. Swap roles."], "title": "Customer journey map and complaint role-play"}, {"steps": ["Ethical selling: help the customer solve their problem; never lie, pressure or hide costs. Trust is the most valuable asset of a small business.", "Sales conversation: greet; ask needs questions ('What is it for?', 'When do you need it?', 'What have you tried?'); recommend and explain benefits; handle objections; ask for the sale ('Shall I put you down for Saturday delivery?').", "Handling objections: price ('It is expensive' - explain value, offer a smaller option, never insult); trust ('How do I know it is good?' - samples, reviews, guarantee); timing ('Maybe later' - ask what would help them decide, follow up once).", "Negotiation preparation: your goal, your options, your walk-away point (the worst deal you will accept), and what the other side needs. Look for win-win - a supplier may give a better price for regular orders or cash payment; a customer may accept a later delivery for a lower price.", "Example: negotiating with a fruit supplier at Wakulima market - buying in bulk twice a week for a 10% lower price in return for reliable payment."], "title": "Sales and negotiation"}, {"steps": ["In groups of three (seller, customer or supplier, observer), run two role-plays: a sales conversation with an objection card, and a supplier negotiation with a goal and walk-away card. The observer gives feedback.", "Each learner writes a short sales script for their business - opening, three needs questions, key benefits, answers to the two most likely objections and a closing question."], "title": "Sales and negotiation role-play and sales script"}, {"steps": ["Ask learners to share the objection they find hardest to handle.", "Set the homework and explain that session 7 is about testing the idea with real customers and preparing the pitch."], "title": "Wrap-up and homework"}], "facilitator": {"delivery": ["Role-plays are the heart of this session; keep lessons short and practice long.", "Point learners who want deeper digital marketing to the Digital Marketing track resources."], "preparation": ["Prepare the templates and the objection and negotiation cards."], "after_session": ["Review the marketing plans and sales scripts and give feedback.", "Record attendance."], "inclusion_and_safeguarding": ["Keep role-plays respectful; no shaming of 'customers' or 'sellers'.", "Remind learners that pressure selling and hidden charges harm customers and the business's reputation."]}, "demonstrations": [{"steps": ["Role-play a poor and a good response to a late-delivery complaint using Listen, Apologise, Fix, Follow up."], "title": "Complaint handling"}, {"steps": ["Role-play a sales conversation with a price objection, showing needs questions and an honest close."], "title": "Sales conversation"}], "assessment_guides": [{"guide": "Names a real alternative and a believable difference.", "question": "Write your positioning sentence."}, {"guide": "Listen, Apologise, Fix, Follow up.", "question": "What are the four steps for handling a complaint?"}, {"guide": "Explain value, offer a smaller or different option, never pressure or insult.", "question": "A customer says 'It is too expensive.' Give an ethical response."}, {"guide": "The worst deal you will accept; below it you walk away.", "question": "What is a walk-away point in negotiation?"}, {"guide": "Specific moments that decide whether customers return.", "question": "Name two moments of truth in your customer journey."}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"f5d6f12c-4432-4541-9106-d750324cccdb","session_id":"3b443948-c867-4209-810d-8a50039a8db5","content":{"version": "V13.2", "segments": [{"steps": ["Ask learners what kinds of posts got the most engagement for the businesses they followed. Group the answers (behind the scenes, offers, tips, customer photos, humour).", "Link to today - those patterns become content pillars."], "title": "Recap and what businesses post"}, {"steps": ["Define brand: what people feel and expect from a business. The logo is only a symbol. Ask learners to describe the feeling of two well-known Kenyan brands (for example a telecom company and a local dairy) in three words.", "Teach the parts of brand identity: name; brand promise (one sentence on what customers can always expect, for example 'Fresh cakes, on time, exactly as in the photo'); personality (three adjectives - warm, reliable, playful); voice (how it writes - friendly English with a little Sheng or Kiswahili, or formal); visual identity (two or three colours, one or two fonts, photo style, logo).", "Show the Shiru's Bakes mini-kit: promise, personality 'warm, reliable, celebratory', voice examples ('Karibu!', 'Your celebration, our pleasure'), colours (a warm pink, cream, chocolate brown with their codes), fonts (one bold heading font, one clean body font), photo style (natural light, real cakes, customers' smiles with consent).", "Consistency: the same name, profile image, colours and voice across all platforms make a small business look trustworthy. Show an inconsistent example (different names and logos on each platform) and ask what customers might think.", "Ethics: do not copy another brand's logo, name or designs; this can confuse customers and infringe trademarks or copyright."], "title": "Branding and brand identity"}, {"steps": ["Learners complete the brand mini-kit template - promise, three personality words, voice (three example phrases), two or three colours with codes, fonts and photo style. If the business already has a brand, they document it and suggest one improvement.", "In Canva (or similar), learners create a simple brand kit page or a screenshot of colours and fonts. Learners without a device do it on paper with coloured pens.", "Two volunteers show their kits; the group checks whether the visuals match the personality words."], "title": "Create your brand mini-kit"}, {"steps": ["Explain content pillars - three or four themes the business always posts about, linked to persona needs. Shiru's Bakes - (1) Celebration ideas, (2) Behind the scenes (baking, delivery), (3) Happy customers (reviews and photos with consent), (4) Offers and how to order.", "Content mix: not every post should sell. A simple rule - for every sales post, share two or three posts that help, entertain or build trust.", "Show the calendar template: date, platform, format (photo, carousel, reel, status, broadcast), pillar, idea, hook (first line), call to action, owner, status (idea, drafted, designed, scheduled, posted).", "Plan around Kenyan dates: month-end paydays, school opening and closing, Madaraka, Mashujaa and Jamhuri holidays, the festive season, exam periods, local events. Say: a realistic calendar (three to four posts a week) that is followed beats an ambitious one that is abandoned.", "Explain batching - create several posts in one sitting and schedule them (Meta Business Suite can schedule Facebook and Instagram posts)."], "title": "Content pillars and the content calendar"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["Learners write their three or four pillars, then fill a two-week calendar with at least six posts and two WhatsApp status or broadcast items, across their chosen platforms.", "Each entry needs a pillar, format, idea, hook and call to action.", "Check that the calendar includes at least one post for each pillar and no more than one third sales posts."], "title": "Build your two-week content calendar"}, {"steps": ["Teach five principles with good and bad examples: (1) hierarchy - one main message biggest, then detail, then call to action; (2) contrast - dark text on light backgrounds or the reverse, never yellow on white; (3) alignment - line elements up, do not scatter; (4) white space - leave breathing room, fewer words; (5) readability - test the design at phone size, use at most two fonts.", "Show the 3-second test: if someone scrolling cannot understand the post in 3 seconds, simplify it.", "Mention sizes: square 1080 x 1080 for feed posts, vertical 1080 x 1920 for stories, reels and status, 1080 x 1350 portrait for Instagram feed.", "Prefer real product photos over stock photos where possible - customers trust real images."], "title": "Visual communication principles"}, {"steps": ["Live in Canva: create a 1080 x 1080 design, upload a real product photo, apply brand colours and fonts, write a headline (for example 'Birthday cakes delivered on time in Ruiru'), add price or offer, and a call to action ('Order on WhatsApp 07XX XXX XXX'). Show how to remove clutter.", "Show how to resize the design for status or stories and how to download it as PNG.", "Learners design two graphics from their calendar (one feed post and one status or story) using their brand mini-kit. Remind them to use their own photos, the business's photos with permission, or images with a licence that allows use."], "title": "Demonstration and practice - designing marketing graphics"}, {"steps": ["In pairs, learners show their graphic for 3 seconds; the partner says what the message is. If they get it wrong, the designer notes one change.", "Run two or three quick assessment questions aloud."], "title": "Peer review and knowledge check"}, {"steps": ["Remind learners that brand kit, calendar and graphics all go into the campaign folder.", "Set the homework."], "title": "Wrap-up and homework"}], "facilitator": {"delivery": ["Learners often spend too long choosing colours; give a time limit and allow them to refine later.", "Push for real photos of the business; offer tips for taking them with a phone (natural light near a window, clean background)."], "preparation": ["Prepare the Shiru's Bakes mini-kit, a good and bad graphic for each principle, and the calendar template.", "Test Canva login and screen sharing; prepare a downloaded template in case of connectivity issues.", "Prepare a list of Kenyan calendar dates for the next two months that learners can plan around."], "after_session": ["Give feedback on each calendar in DIRA LEARN (balance of pillars, realistic frequency).", "Record attendance."], "inclusion_and_safeguarding": ["Remind learners to get consent before using photos of customers or staff, and never to use images of children without their parent's or guardian's consent.", "Learners must not copy other brands' logos or designs.", "Consent and privacy: before using an identifiable person (face, voice or name), a photograph of someone, or a real business's name, logo, prices, customer details or results, the learner gets permission from that person or owner - in writing (a WhatsApp message is enough) for anything shown outside the class. Never children. Learners who cannot or do not wish to publish publicly use the private or simulated option, which is assessed with the same rubric and never marked down."]}, "demonstrations": [{"steps": ["Show a complete mini-kit for Shiru's Bakes and explain each choice."], "title": "Brand mini-kit"}, {"steps": ["Create, apply brand kit, write hierarchy, add CTA, resize for status, download."], "title": "Designing a marketing graphic in Canva"}], "assessment_guides": [{"guide": "The brand is what people feel and expect; the logo is a visual symbol of it.", "question": "What is the difference between a brand and a logo?"}, {"guide": "Specific, believable, customer-focused (for example 'Fresh, on time, exactly as shown').", "question": "Write a brand promise for your business in one sentence."}, {"guide": "Repeating themes linked to audience needs; they make planning easier and keep content consistent.", "question": "What are content pillars and why use them?"}, {"guide": "Hierarchy, contrast, alignment, white space, readability.", "question": "Name three visual communication principles."}, {"guide": "Too much selling; audiences disengage. Add posts that help, entertain or build trust.", "question": "Your calendar has 10 posts and 8 are sales posts. What is the problem?"}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}, {"id":"f9f108fe-6531-4425-940c-4ad23a7cc66f","session_id":"86656270-aaa1-472b-bda9-d1a65186e185","content":{"version": "V13.2", "segments": [{"steps": ["Welcome learners and guests (local entrepreneurs, DIRA staff, mentors, potential partners). Thank interviewees and test customers.", "Share the rubric: problem and customer (20%), solution and value proposition (15%), evidence from testing (25%), business model and numbers (20%), pitch delivery and answers (20%).", "Assign each learner two presenters to give written feedback to."], "title": "Showcase set-up and expectations"}, {"steps": ["Run the pitches with the session 8 room plan in the facilitator instructions: the first six pitchers in each room go in this block, each with 3 minutes plus 2 minutes of questions.", "Learners pitch in order, 3 minutes each plus 2 minutes of questions. Strict timer with a 30-second warning.", "Ask at least one question per presenter, such as: 'How many customers have actually paid?', 'What is your break-even and how long will it take to reach?', 'What did your test tell you?', 'What would you do with KES 10,000?', 'What is your biggest risk?'", "Score with the rubric and note one strength and one improvement."], "title": "Pitches and questions - block 1"}, {"steps": ["Invite everyone to stand, stretch, walk or drink water for five minutes; offer a seated option for anyone who prefers or needs it.", "Restart on time with a one-line reminder of where the session is and what comes next."], "title": "Stretch break"}, {"steps": ["The remaining pitchers in each live room (7 to 12) go now, with the same timer, rubric and question approach as block 1.", "In a recorded-questions room, do not replay the recordings (the panel scored them before the session); give each recorded presenter 2 minutes of live questions about their business pitch.", "Each room's panel hands its completed business pitch rubric sheets to the room facilitator before the feedback round."], "title": "Pitches and questions - block 2"}, {"steps": ["Learners give written feedback to their two assigned presenters.", "Facilitator highlights patterns in strong pitches - real evidence, honest numbers, a clear ask.", "Model receiving tough feedback calmly - thank, clarify, decide."], "title": "Feedback round"}, {"steps": ["Entrepreneur self-pitch: 'I am Kevin from Kitui. I test ideas with real customers before spending money. I tested a solar lamp rental with five households; four paid on time and two referred neighbours. I am looking for a partner with a motorbike to expand deliveries.'", "Employability: the project shows skills employers want - research, numeracy, customer service, sales, presenting and taking initiative. Practise describing it in an interview using situation, action and result.", "Pathways: starting the business in small steps, joining a small business, employment while building the business on the side, further training; support networks such as county enterprise offices, youth business programmes and DIRA alumni. Beware of 'business opportunities' that ask for joining fees or promise quick returns (pyramid schemes).", "Professional follow-up: thank guests and test customers within two days; follow up on any offer of help with a short, specific message.", "Learners practise their self-pitch once in pairs."], "title": "Pitching yourself and workplace readiness"}, {"steps": ["Learners complete the 30-day validation plan: the main assumption still to test, the next validation step (for example 'get 20 paying customers', 'run a two-week pilot'), four weekly actions, a measure of success, an accountability partner, one risk and a plan.", "Learners share their next validation step with their accountability partner."], "title": "30-day validation action plan"}, {"steps": ["Celebrate each learner's pitch in one sentence.", "Explain how to submit the pitch deck, concept summary and 30-day validation action in DIRA LEARN, how results and certificates follow the programme's rules, and how alumni can connect with mentors and youth enterprise funding information."], "title": "Celebration and close"}], "facilitator": {"delivery": ["Keep strict time; protect nervous presenters from harsh questioning.", "Celebrate learners who changed or stopped ideas based on evidence.", "Session 8 room plan - Room plan (set in session 7 from the track group size; the session is never extended): up to 12 learners - one room; 13 to 24 - two rooms in parallel; 25 to 36 - three rooms, or two live rooms plus one recorded-questions room. Each live room takes at most 12 presenters: 6 in each 30-minute block, 3 minutes to present and 2 minutes of questions each.", "Every room has a facilitator or briefed co-facilitator (another trainer, a mentor or DIRA staff member who knows the rubric and the safeguarding expectations) and a peer panel of two learners who present in the other block. All rooms use the same rubric.", "Recorded option: learners in a recorded-questions room, and anyone who cannot present live (absence, connection problems, anxiety, or the privacy option), submit a 3-minute recording - video, or a voice note with slides for low data - by the day before session 8. The panel scores it in advance with the same rubric; in session 8 each recorded presenter answers 2 minutes of live questions (12 per block). If more learners need the recorded option than one room can take, the panel sends written questions and the learner answers them in DIRA LEARN.", "Timekeeping: a visible timer with a 30-second warning; stop at 3 minutes. If a block runs late, cut questions to 1 minute - do not extend the session."], "preparation": ["Publish the pitch order; check slides or visuals work.", "Invite guests (local entrepreneurs, partners) and brief them on respectful questions and safeguarding expectations.", "Confirm the room plan: count the learners in the track group, book the rooms and co-facilitators, brief the peer panels, and publish each room's presenter order and the list of recorded presenters by the end of session 7."], "after_session": ["Enter rubric scores and feedback in DIRA LEARN grading.", "Record attendance."], "inclusion_and_safeguarding": ["Learners who cannot present live can submit a recorded pitch according to the programme's rules.", "Guests must not make funding or business offers directly to learners outside programme channels; route any offers through DIRA staff."]}, "demonstrations": [{"steps": ["Before the session, share the recorded Fresh Fold example pitch as a reference. Do not use showcase time for it."], "title": "Model pitch"}], "assessment_guides": [{"guide": "Use rubric descriptors; evidence and honest numbers weigh most.", "question": "Pitch scored with the business pitch rubric."}, {"guide": "A specific, realistic step with a number.", "question": "What is your next validation step and how will you measure it?"}, {"guide": "Clear situation, own actions and a measurable result.", "question": "Describe your project using situation, action and result."}]},"updated_by":null,"updated_at":"2026-11-21T19:24:48.274223+03:00","created_at":"2026-11-21T19:24:48.274223+03:00"}]$dira_json$::jsonb); alter table public.curriculum_teaching_notes enable trigger user;
